// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Edebî terimler, anlatıcı, bakış açısı ve metin çözümleme (orta).
const ozLiterature14Orta = <(String, String, List<String>, String)>[
  ('\'Sofraya on can oturduk.\' cümlesinde \'can\' sözcüğü ile kişiler anlatılmıştır. Bu ad aktarması hangi ilgiye dayanır?', 'Parça ile bütünü anlatma', ['Neden ile sonucu anlatma', 'Kap ile içindekini anlatma', 'Yazar ile eseri anlatma'], 'Can, insanın bir parçası olarak bütün insanı anlatmak için kullanılmıştır.'),
  ('Mecaz-ı mürsel ile istiare arasındaki temel fark aşağıdakilerden hangisidir?', 'İstiarede benzetme ilgisi vardır; mecaz-ı mürselde benzerlik dışında bir ilgi vardır.', ['İstiare yalnız nesirde, mecaz-ı mürsel yalnız nazımda görülür.', 'Mecaz-ı mürselde gerçek anlam kastedilir, istiarede kastedilmez.', 'İstiarede iki söz birden anlatılır, mecaz-ı mürselde yalnız bir söz.'], 'Mecaz-ı mürsel bir benzetmeye değil; yer, parça, neden gibi ilgilere dayanır.'),
  ('\'Kalemi kuvvetli bir gazeteciydi.\' cümlesinde \'kalem\' sözüyle neyin kastedildiğini en doğru biçimde hangi seçenek verir?', 'Yazı yazma gücü ve yeteneği', ['Gazetecinin yazı aracı olan nesne', 'Gazetecinin çalıştığı yer', 'Gazetecinin yazdığı son makale'], 'Kalem, araç olarak onunla yapılan işi (yazma yeteneğini) anlatmak için kullanılmıştır.'),
  ('\'Okulumuz bu yıl şampiyon oldu.\' cümlesindeki \'okul\' sözcüğünün kullanımıyla ilgili hangisi doğrudur?', 'Okuldaki öğrenciler anlatıldığı için mecaz-ı mürseldir.', ['Okul bir insana benzetildiği için teşhistir.', 'Okul bir insana benzetildiği için teşhis vardır, okul canlıdır.', 'Okul sözü abartıldığı için mübalağadır.'], 'Okul yer olarak burada içindeki takımı ve öğrencileri anlatır; benzetme yoktur.'),
  ('\'Gür bir sessizlik odayı doldurdu.\' cümlesinde hangi anlatım özelliği vardır?', 'Oksimoron', ['Mübalağa, abartılı anlatım', 'Teşbih, benzetme sanatı', 'Cinas'], 'Sessizlik ile gür sözü birbirine ters olduğu hâlde tek bir ifade içinde birleşmiştir.'),
  ('\'Dostun yüzü gülünce ben yağmur, düşmanın yüzü gülünce ben kış olurum.\' İfadedeki karşıtlık düşünceyi ne yönde etkiler?', 'Duyguların zıtlığı belirginleşerek anlatım güçlenir.', ['Anlatım gizemli hâle gelir ve anlaşılması güçleşir.', 'Söylenen şey kesin bir bilgiye dönüşür.', 'Cümle nesnel bir anlatıma kavuşur.'], 'Karşıt durumların yan yana gelmesi duygunun şiddetini artırır.'),
  ('Paradoksun edebî metinde sık kullanılmasının temel nedeni aşağıdakilerden hangisidir?', 'Okuru şaşırtıp düşünmeye yöneltmek', ['Metni daha kısa hâle getirmek', 'Olayların sırasını kesin biçimde bildirmek', 'Sözcüklerin sesini ahenkli kılmak'], 'Çelişkili görünen söz, okuru yüzeyin ardındaki anlamı aramaya iter.'),
  ('Bir şiirde \'kapalı kapı\' imgesi dizeden dizeye tekrar edilerek hem yalnızlığı hem de ulaşılmazlığı düşündürüyor. Sembolün bu yönü neyi gösterir?', 'Birden çok anlama açık olmasını', ['Yalnızca tek bir anlamı kesin olarak bildirmesini', 'Gerçek anlamda kullanılmasını', 'Aynı sesin tekrarına dayanmasını'], 'Sembol, tek bir anlamla sınırlı kalmayıp okurun yorumuna açık çok anlamlı bir yapı taşır.'),
  ('Bir metinde kırmızı renk, bir yerde aşkı, başka bir yerde tehlikeyi simgeleyebilir. Bu durum sembol için hangi sonucu gösterir?', 'Sembolün anlamı bağlama göre değişebilir.', ['Sembol her zaman evrensel ve sabit anlam taşır.', 'Renkler edebî metinde sembol olamaz.', 'Sembolün anlamı yazarın niyetinden bağımsızdır.'], 'Sembolik anlam metnin bağlamında kurulduğundan aynı nesne farklı metinlerde farklı anlamlar taşıyabilir.'),
  ('Aşağıdakilerden hangisi edebî sembolden çok gündelik hayattaki bir işarete örnektir?', 'Trafik ışığındaki kırmızının \'dur\' anlamına gelmesi', ['Romanda sürekli yağan yağmurun umutsuzluğu düşündürmesi', 'Öyküdeki kafesin özgürlük yoksunluğunu simgelemesi', 'Şiirdeki boş sandalyenin yokluğu anlatması'], 'Trafik ışığı, kesin bir kurala bağlı işarettir; diğerleri yoruma açık edebî simgelerdir.'),
  ('Yazarların baskı dönemlerinde alegoriye sık başvurmasının başlıca nedeni hangisidir?', 'Doğrudan söylenemeyen eleştiriyi örtük biçimde dile getirmek', ['Metni olabildiğince kısa tutmak', 'Okuru olaylara uzak tutmak', 'Kahramanların sayısını azaltmak'], 'Alegori, eleştiriyi simgesel bir hikâyenin ardına yerleştirerek sansürden kaçınmaya olanak verir.'),
  ('Motif ile tema arasındaki ilişki hangi seçenekte doğru verilmiştir?', 'Motifler tekrarlanarak eserin temasını güçlendirir.', ['Tema motifin bir parçasıdır, motif eserin tamamıdır.', 'Motif yalnız şiirde, tema yalnız romanda bulunur.', 'Motif ve tema aynı kavramı anlatan iki sözcüktür.'], 'Motifler eser boyunca yinelenen öğelerdir ve ana temayı pekiştirir.'),
  ('Bir yazar \'ölmek\' sözünü her defasında \'gözlerini dünyaya yummak\' diye anlatıyor. Bu seçim hangi etkiyi güçlendirir?', 'Acı gerçeği dolaylı ve yumuşatılmış bir dille vermeyi', ['Olayların kronolojik sırasını belirlemeyi', 'Karakterin dış görünüşünü betimlemeyi', 'Anlatıcının güvenilmezliğini ortaya koymayı'], 'Örtmece dolaylı anlatım yoluyla sert ya da acı sözleri yumuşatır.'),
  ('Eş anlamlı iki sözcükten biri günlük dilde, diğeri şiirde tercih ediliyorsa bu durum sözcükler arasında neyi gösterir?', 'Duygu değeri ve üslup farkını', ['Anlam bakımından tam bir özdeşliği', 'Sözcüklerden birinin yabancı kökenli olduğunu', 'Aynı sözcüğün iki ayrı yazılışı olduğunu'], 'Eş anlamlı sözcükler çağrışım gücü ve kullanım alanı bakımından farklılaşabilir.'),
  ('Tema ile ana düşünce arasındaki ilişkiyi en iyi hangisi açıklar?', 'Tema eserin üzerine kurulduğu konudur; ana düşünce yazarın o konuda vermek istediği yargıdır.', ['Tema ile ana düşünce her zaman aynı sözcükle ifade edilir.', 'Ana düşünce yalnız şiirde, tema yalnız romanda bulunur.', 'Tema yazarın kişisel görüşüdür, ana düşünce konunun adıdır.'], 'Tema \'yalnızlık\' gibi kısa bir kavramdır; ana düşünce ise bu konuda söylenen yargıdır.'),
  ('\'Yalnızlık\' temalı bir şiirde şair yalnızlığın insanı olgunlaştırdığını savunuyorsa şiirin ana düşüncesi aşağıdakilerden hangisi olur?', 'Yalnızlık insanı olgunlaştıran bir deneyimdir.', ['Yalnızlık bir temadır.', 'Şair yalnız yaşar.', 'Şiirde yalnızlık sözcüğü sık geçer.'], 'Ana düşünce, temayla ilgili yazarın vardığı ve savunduğu yargıdır.'),
  ('Bir metinde \'Su, tasarruflu kullanılmazsa gelecek kuşaklar susuz kalır\' deniyor ve sonra evlerde, tarımda ve sanayide su tasarrufunun yolları anlatılıyor. Bu parçadaki \'tarımda su tasarrufu\' bilgisi için hangisi doğrudur?', 'Ana düşünceyi destekleyen yardımcı düşüncedir.', ['Metnin teması değil ana düşüncedir.', 'Konudan sapmadır.', 'Metinde paragraf bozukluğudur.'], 'Ana düşünceyi açıklayan, örnekleyen ayrıntılar yardımcı düşünceyi oluşturur.'),
  ('Ana düşünce bir şiirde açıkça söylenmeyip okurun çıkarmasına bırakılıyorsa bu durum şiirde hangi özelliği gösterir?', 'Dolaylı anlatım ve imgeye dayalı bir dil kullanıldığını', ['Öğretici bir dil kullanıldığını', 'Anlatım biçiminin açıklama olduğunu', 'Metnin makale türünde olduğunu'], 'Şiir, yargıyı doğrudan söylemek yerine imgeler yoluyla sezdirir.'),
  ('Aynı konuyu işleyen iki öykünün ana düşünceleri farklı olabilir mi?', 'Evet, çünkü ana düşünce yazarın konudaki yargısına göre değişir.', ['Hayır, çünkü aynı konu her zaman aynı yargıyı doğurur.', 'Hayır, çünkü ana düşünce konuyla özdeştir.', 'Evet, çünkü iki öyküde temaların farklı olması zorunludur.'], 'Konu aynı olsa da yazarlar o konuda farklı yargılara varabilir.'),
  ('Bir yazar, çocuk yaşta yoksulluğun getirdiği zorlukları anlatırken kahramanın bir gün okula gidemediğini, ertesi gün elbisesinin yırtık olduğunu anlatıyor. Bu ayrıntılar için hangisi doğrudur?', 'Yoksulluk temasını destekleyen yardımcı öğelerdir.', ['Eserin ana temasını yok eder.', 'Anlatıcının güvenilmezliğini gösterir.', 'Eserde kronolojik bozukluk yaratır.'], 'Bu ayrıntılar ana temayı somutlaştıran yardımcı öğelerdir.'),
  ('Bir metinde \'Dürüstlük, uzun vadede her zaman kazandırır; çünkü güven, ticaretin temelidir.\' deniyor. Bu cümlede \'çünkü\' ile başlayan kısım ne işlev görür?', 'Ana düşünceyi gerekçelendirir', ['Konuyu değiştirir', 'Betimleme yapar', 'Anlatıcıyı tanıtır'], 'Gerekçe bildiren kısım, ana yargıyı destekleyen düşüncedir.'),
  ('Bir şiirde \'ölüm\' sözcüğü hiç geçmediği hâlde dizeler boyunca solan çiçekler, sönen mumlar ve kapanan perdeler anlatılıyorsa bu şiirin teması için ne söylenebilir?', 'Ölüm teması imgeler yoluyla dolaylı olarak işlenmiştir.', ['Şiirin teması doğa sevgisidir.', 'Şiirin teması belli değildir.', 'Şiir didaktik bir metindir.'], 'Sözcük geçmese de imgeler ölüm temasını çağrıştırır.'),
  ('Bir hikâyede kahramanın kardeşi sınavı kazanamıyor, yine de hiç yılmayıp çalışmaya devam ediyor. Bu kısımla ilgili aşağıdakilerden hangisi doğrudur?', 'Azim ve çabanın değeri düşüncesini destekler.', ['Kahramanın bakış açısını gösterir.', 'Eserin mekânını belirtir.', 'Zamanda geriye dönüşü gösterir.'], 'Pes etmeden çabalamak, azim temasına bağlı bir yardımcı öğedir.'),
  ('Bir romanda anlatıcı, olayların içinde yer alan ama kahraman olmayan, olup biteni uzaktan izleyip aktaran bir kişidir ve ana kahramanın düşüncelerini yalnız tahmin edebilir. Bu anlatıcıya hangi ad verilir?', 'Tanık anlatıcı', ['Ansiklopedik anlatıcı', 'Çoğul anlatıcı', 'Evrensel anlatıcı'], 'Olayların içinde olup kahraman olmayan, gözlediklerini aktaran anlatıcı tanık anlatıcıdır.'),
  ('Anlatıcı çocuk olduğu için yetişkinlerin dünyasını yanlış ya da eksik anlıyor, okur ise gerçek durumu fark ediyor. Bu tür anlatıcının işlevi ne olur?', 'Okurda ironi ve ek anlam yaratmak', ['Olayları kronolojik sıraya sokup zamanı düzeltmek', 'Kahramanları tanıtmak', 'Mekânı ayrıntılı betimlemek'], 'Naif anlatıcının yanlış kavrayışı, okurun doğruyu sezmesiyle ironi doğurur.'),
  ('Yazar ile anlatıcı arasındaki ilişkiyi hangi ifade en doğru biçimde belirtir?', 'Yazar gerçek kişidir; anlatıcı yazarın kurguda yarattığı sestir.', ['Yazar ile anlatıcı her zaman aynı kişidir.', 'Anlatıcı yazarın otobiyografisidir.', 'Anlatıcı yalnızca kahramandır.'], 'Anlatıcı kurmacanın bir parçasıdır; yazarla özdeş sayılmaz.'),
  ('Bir roman, ilk bölümde annenin, ikinci bölümde kızın, üçüncü bölümde oğulun kendi sesinden anlatılıyor. Bu yapının sağladığı etki hangisidir?', 'Aynı olayın farklı kişilerce farklı yorumlanması', ['Anlatıcının tek yönlü ve kesin bir hüküm vermesi', 'Olayların hep aynı bakışla ve aynı sesle aktarılması', 'Olay örgüsünün tek çizgide ilerlemesi'], 'Çok sesli anlatım, olayların birbirinden farklı bakışlarla sunulmasını sağlar.'),
  ('Bir anlatıcı, gerçekleri bildiği hâlde okurdan saklayıp son sayfada açıklıyorsa aşağıdakilerden hangisi için olasılık yüksektir?', 'Merak ve sürpriz etkisi yaratmak amaçlanmıştır.', ['Metin bilimsel bir yazıdır.', 'Metin bir günlüktür.', 'Metin tarihî romandır.'], 'Bilgiyi geç vererek anlatıcı merakı canlı tutar.'),
  ('Bir öykü, sadece bir yaşlı balıkçının gözünden anlatılıyor ve balıkçının bilmediği şeyler anlatıya yansımıyor. Bu anlatıcı için en yakın nitelik hangisidir?', 'Sınırlı bilgiye sahip anlatıcı', ['Her şeyi bilen ve kahramanın bilmediğini de aktaran anlatıcı', 'Okurla alay eden ve olayları çarpıtan anlatıcı', 'Belgesel anlatıcı'], 'Anlatıcı yalnız kahramanın bildikleriyle sınırlıdır.'),
  ('Bir romanda anlatıcı, gerçek yazarın tarihî dönem bilgilerini olay akışından bağımsız olarak uzun uzun anlatıyor. Bu müdahale en çok hangi anlatıcı türünü akla getirir?', 'Her şeyi bilen anlatıcı', ['Naif anlatıcı, olayları saf bir bakışla aktaran', 'Tanık anlatıcı', 'Güvenilmez anlatıcı'], 'Olayların dışında kalıp bilgi ve yorum ekleyen anlatıcı her şeyi bilen anlatıcıdır.'),
  ('\'Adam kapıyı çaldı, kimse açmadı. Bir süre bekledikten sonra elini cebine attı ve çıkardığı anahtarla kapıyı açtı.\' parçasındaki anlatım için hangisi söylenebilir?', 'Dışarıdan bakan, iç dünyaya girmeyen bir anlatım vardır.', ['Kahramanın duyguları ayrıntılı verilmiştir.', 'Anlatıcı her şeyi bilmektedir.', 'Anlatı birinci kişili iç monologdur.'], 'Kahramanın düşünceleri verilmediği için dışsal bir bakış söz konusudur.'),
  ('İçsel odaklamanın okur üzerindeki en belirgin etkisi hangisidir?', 'Okurun kahramanın algısına ve duygusuna yakınlaşması', ['Okurun olayların dışında kalması', 'Olayların tamamının önceden bilinmesi', 'Kahramanın şüpheli görünmesi'], 'İçsel odaklama okuru kahramanın zihnine yaklaştırır.'),
  ('Bir yazar, aynı olayı önce bir çocuğun, sonra yaşlı bir adamın gözünden anlatıyor. Bu seçimin amacı en çok hangisidir?', 'Olayın farklı yorumlanabilirliğini göstermek', ['Olayı kronolojik kılmak', 'Anlatıcıyı gizlemek', 'Mekânı değiştirmek'], 'Aynı olayın farklı algılara göre farklılaşması gösterilmek istenir.'),
  ('Aşağıdaki cümlelerin hangisi sıfır odaklamayla yazılmış bir anlatıya aittir?', 'Kız o sırada hiç bilmediği bir acının eşiğinde olduğunu bilmiyordu; oysa mektup postaneden yola çıkmıştı bile.', ['Pencereden baktım, sokak boştu.', 'Adam kapıdan çıktı, yürüdü.', 'Sana dönüp baktığımda yüzünün solduğunu gördüm.'], 'Anlatıcı kahramanın bilmediklerini de bildiği için sıfır odaklama vardır.'),
  ('Bir öyküde \'Üç yıl sonra kızı üniversiteyi bitirmiş olacaktı; ama bunu o gün kimse bilmiyordu.\' cümlesi anlatıyı geleceğe taşıyor. Bu teknik nedir?', 'İleri sıçrama', ['Geçmişi hatırlama yoluyla geriye dönüş', 'Aynı olayı farklı gözden anlatma', 'Anlatıcıyı gizleme'], 'Gelecekteki bir olayı önceden bildirmek ileri sıçrama (öncül anlatım) tekniğidir.'),
  ('Bir romanda ilk bölüm kahramanın ölümüyle başlıyor, sonraki bölümler ise yaşamını baştan anlatıyor. Bu yapı için hangisi uygundur?', 'Sondan başlayan, geriye dönüşlü kurgu', ['Çerçeve öyküsüz, olayları baştan sona sıralayan kronolojik kurgu', 'Alegorik kurgu, olaylara ikinci anlam yükleyen yapı', 'Şiirsel kurgu'], 'Sondan başlayıp geriye doğru anlatan yapı geriye dönüşlü bir kurgudur.'),
  ('Bir yazar, aynı gün içinde farklı yerlerde olan olayları sırayla ama kesilerek aktarıyor: \'Bu sırada İstanbul\'da...\' \'Aynı anda Ankara\'da...\' Bu teknik nedir?', 'Paralel anlatı', ['Çerçeve öykü, bir anlatıyı kuşatan öykü', 'Geriye dönüş', 'Duraklama'], 'Aynı zaman diliminde olup biten farklı olayların dönüşümlü anlatılması paralel anlatıdır.'),
  ('Kronolojik sıralamanın bozulması bir anlatıda hangi sonucu doğurabilir?', 'Merak ve gerilimin artması', ['Anlatıcının otomatik olarak güvenilir olması', 'Olay örgüsünün ortadan kalkması', 'Metnin bilimsel bir yazıya dönüşmesi'], 'Olayların sırasının değiştirilmesi, okurda merak uyandırır.'),
  ('Bir romanda \'dün\', \'bugün\' ve \'yarın\' bölümleri birbirine karıştırılarak sunuluyorsa bu duruma hangi ad verilir?', 'Doğrusal olmayan zaman kurgusu', ['Kronolojik düzen', 'Alegorik zaman', 'Çoğul anlatıcı'], 'Zamanın düz çizgi yerine karışık sunulması doğrusal olmayan kurgudur.'),
  ('Bir kahramanın günlük yaşamının bir günde anlatıldığı romanlar için aşağıdakilerden hangisi doğrudur?', 'Zaman dar tutulmuş, ayrıntıya yer verilmiştir.', ['Zaman yıllarca uzar.', 'Anlatıda zaman hiç kullanılmaz.', 'Roman şiire dönüşür.'], 'Bir günlük yaşam anlatılırken sahneler ayrıntılı kurulur ve zaman dar bir aralıkta tutulur.'),
  ('Bir öykünün bütün olayları, kapıları dışarıdan kilitli bir odada geçiyorsa bu mekân tercihi anlatıya en çok hangi etkiyi katar?', 'Sıkışmışlık ve gerilim', ['Geniş bir doğa izlenimi ve özgürlük duygusu', 'Çok sayıda kahramanın tanıtılması', 'Tarihî dönemin ayrıntılı gösterilmesi'], 'Kapalı ve dar mekân, kahramanın sıkışmışlığını ve gerilimi artırır.'),
  ('Bir romanda sürekli yağmurlu, sisli ve gri bir şehir betimleniyor. Bu betimlemenin başlıca amacı nedir?', 'Hüzünlü ve kasvetli bir atmosfer kurmak', ['Şehrin nüfusunu kesin sayılarla bildirmek', 'Olayların kronolojisini düzeltmek', 'Anlatıcının güvenilir olduğunu göstermek'], 'Hava durumu ve renk ayrıntıları atmosfer yaratır.'),
  ('Bir romancı gerçek bir şehri, adını da kullanarak ayrıntılı biçimde betimliyor ve olayları bu şehrin gerçek semtlerinde geçiriyor. Bu yaklaşımın etkisi hangisidir?', 'Gerçeklik izlenimi güçlenir', ['Eser mutlaka tarihsel belge olur', 'Metin otomatik olarak alegori olur', 'Anlatıcı güvenilmez hâle gelir'], 'Gerçek mekânın kullanılması kurmacaya gerçeklik izlenimi katar.'),
  ('Bir kahramanın ruh hâlini yansıtan \'kuru dallı ağaçlar, rüzgârın ıslık sesi, bulutlarla kaplı gökyüzü\' gibi doğa ögeleri bir arada kullanılmışsa bu anlatım tekniği için hangisi söylenebilir?', 'Doğa ile ruh hâli arasında paralellik kurulmuştur.', ['Yazar yalnız bilimsel bilgi aktarmaktadır.', 'Kahramanın adının bilerek gizlendiği bir anlatım söz konusudur.', 'Olay örgüsü kopmuştur.'], 'Doğa betimi kahramanın iç dünyasıyla örtüşecek biçimde seçilmiştir.'),
  ('Bir yazar olayları bir otel koridorunda başlatıp aynı koridorda bitiriyor ve başka hiçbir mekâna geçmiyor. Bu yaklaşım hangi yapı özelliğini akla getirir?', 'Mekân birliği', ['Üç birlik kuralının bozulması', 'Alegorik kurgu', 'Çoğul anlatıcı'], 'Tek mekânda geçen anlatı mekân birliğini sağlar.'),
  ('Bir öykünün atmosferini \'ürpertici\' hâle getirmek isteyen yazarın aşağıdaki seçeneklerden hangisini tercih etmesi beklenir?', 'Karanlık, ıssız ve sessiz bir yerde geçen sahneler', ['Sıcak renkli bir pazar yeri betimi', 'Neşeli çocuk sesleriyle dolu bir bahçe', 'Kalabalık bir bayram kutlaması'], 'Ürpertici hava; karanlık, ıssızlık ve sessizlikle kurulur.'),
  ('Bir yazarın bir şehri yalnız dış görünüşüyle değil, orada yaşayanların huy ve tavırlarıyla da betimlemesi o şehrin hangi yönünü ortaya koyar?', 'Toplumsal ve kültürel dokusunu', ['Yalnızca coğrafi konumunu ve iklimini', 'Yalnızca iklim bilgisini', 'Yalnızca tarihî olaylarını'], 'Yaşayanların davranışları, mekânın toplumsal kimliğini gösterir.'),
  ('\'Kadın, yılların yorgunluğunu omuzlarında taşıyan, ama gülüşüyle bütün odayı aydınlatan biriydi.\' cümlesindeki betimleme için hangisi doğrudur?', 'Hem fiziksel hem ruhsal özellikler verilmiştir.', ['Yalnız dış görünüş verilmiştir.', 'Yalnız mekân betimlenmiştir.', 'Yalnız öyküleme vardır.'], 'Hem yorgunluk (ruhsal) hem gülüş (davranış) anlatılarak çok yönlü bir portre sunulmuştur.'),
  ('Bir yazar, kahramanını sadece diğer kişilerin onun hakkında söylediklerinden ve davranışlarından tanıtıyor; hiçbir zaman \'cimriydi\' ya da \'merhametliydi\' demiyor. Bu tanıtma biçimi hangisidir?', 'Dolaylı karakterizasyon', ['Doğrudan karakterizasyon', 'İç monolog', 'Kronolojik anlatım'], 'Davranış ve söz aracılığıyla yapılan tanıtma dolaylı karakterizasyondur.'),
  ('Bir oyunda hiçbir kişisel özelliği olmayan, yalnızca \'cimri\', \'korkak\' gibi bir davranışı temsil eden kişi için aşağıdakilerden hangisi doğrudur?', 'Tip niteliği taşır.', ['Yuvarlak karakterdir.', 'Güvenilmez anlatıcıdır.', 'Dinamik karakterdir.'], 'Tek bir davranışı temsil eden kişi tip sayılır.'),
  ('Bir olay örgüsünde olaylar arasında \'şundan dolayı bu oldu\' biçiminde bir neden–sonuç bağı bulunması neyi sağlar?', 'Anlatının tutarlı ve inandırıcı olmasını', ['Anlatıcının güvenilmezliğini', 'Zamanın belirsizliğini', 'Mekânın kapalı olmasını'], 'Nedensellik olayları birbirine bağlayarak inandırıcılık sağlar.'),
  ('Olayların birbirini hiç etkilemeyen ve gelişigüzel sıralanan bir yapıda kurulduğu anlatımlarda eksik olan öğe hangisidir?', 'Nedensellik bağı', ['Mekân bilgisi ve ayrıntılı betimleme', 'Bakış açısı', 'Kişi sayısı'], 'Olay örgüsünü oluşturan şey olaylar arasındaki neden–sonuç ilişkisidir.'),
  ('Okurun merakını sürdürmek için yazarın olayların nedenini ya da kişiyi geç açıklaması hangi tekniktir?', 'Gizleme ile gerilim kurma', ['Betimlemeyle duraklamaya gidip akışı yavaşlatma', 'Bilinç akışıyla anlatım', 'Çerçeve öykü'], 'Bilgiyi geciktirmek gerilim ve merak yaratır.'),
  ('Diyalogların bir anlatıdaki başlıca işlevlerinden biri aşağıdakilerden hangisidir?', 'Kişilerin özelliklerini ve olayın gelişimini canlı biçimde sunmak', ['Mekânın ayrıntılarını sıralamak', 'Anlatıcının görüşlerini gizlemek', 'Zamanı geriye sarmak'], 'Diyalog kişileri konuşturarak tanıtır ve olayı ilerletir.'),
  ('Bir yazarın konuşmaları tırnak işareti ve konuşma çizgisi kullanmadan, anlatı cümlelerinin içine yedirerek vermesi için aşağıdakilerden hangisi söylenebilir?', 'Anlatıcı sesiyle kişi sesi arasındaki sınırı bulanıklaştırmıştır.', ['Metin tiyatro oyunudur.', 'Metin bir günlüktür.', 'Metin bir makaledir.'], 'Konuşmaların tırnaksız verilmesi, anlatıcı ile kişi sesini birleştirir.'),
  ('Bilinç akışı tekniğinde noktalama işaretlerinin azalması ya da yok olması en çok hangi amaçla yapılır?', 'Düşüncenin kesintisiz ve düzensiz akışını yansıtmak', ['Okuru dilbilgisi kurallarıyla sınamak', 'Anlatıcıyı güvenilir kılmak', 'Olayları kronolojik düzenlemek'], 'Noktalamanın kalkması zihnin kesintisiz akışını duyurur.'),
  ('Bir hikâyede mektup ve günlük sayfalarının doğrudan metne yerleştirilmesinin etkisi hangisidir?', 'Belge gerçekliği ve içtenlik izlenimi', ['Anlatıcının evrensel bakışı', 'Zamanın kronolojik olması', 'Mekânın evrenselleşmesi'], 'Belge biçimindeki metinler, gerçeklik ve içtenlik duygusu verir.'),
  ('Bir romanda, bir kitabın içinde başka bir kitabın okunması, bir anlatının içinde başka bir anlatıcının anlatı kurması örneğinde hangi yapısal özellik vardır?', 'İç içe anlatı', ['Kronolojik anlatı', 'Dışsal odaklama', 'Betimleme'], 'Anlatı içinde başka bir anlatı iç içe anlatıdır.'),
  ('Gelişmiş bir anlatıda kullanılan \'dolaylı aktarma\' ile \'doğrudan aktarma\' arasındaki fark hangisidir?', 'Doğrudan aktarmada sözler olduğu gibi, dolaylı aktarmada anlatıcı ağzından verilir.', ['Doğrudan aktarma yalnızca şiirde bulunur.', 'Dolaylı aktarmada sözler tırnak içinde verilir.', 'Doğrudan aktarmada konuşma hiç verilmez.'], 'Doğrudan aktarma sözü olduğu gibi, dolaylı aktarma aktarılan kişi cümlesiyle verir.'),
  ('Bir çerçeve öyküde dış öykü ile iç öyküler arasındaki ilişki hangisidir?', 'Dış öykü iç öyküleri başlatır ve çerçeveler.', ['İç öyküler dış öyküyü yok eder.', 'Dış öykü her zaman şiirdir.', 'İç öyküler dış öykünün eleştirisidir.'], 'Dış öykü çerçeveyi, iç öyküler asıl anlatıları oluşturur.'),
  ('Bir anlatıcının anlattığı hikâyedeki kahraman, başka bir hikâye anlatmaya başlıyor ve bu durum üç katman boyunca sürüyor. Bu yapının sağladığı etki hangisidir?', 'Katmanlı ve labirent benzeri bir anlatı', ['Doğrusal ve tek katmanlı, düz bir anlatı', 'Yalnızca betimleme ağırlıklı anlatı', 'Sadece tiyatro oyunu etkisi'], 'Katmanlar arasında geçiş, labirent gibi çok katmanlı bir yapı oluşturur.'),
  ('Çerçeve öykünün gerçeklik izlenimi kazandırmak için sık kullandığı yöntem hangisidir?', 'Anlatılanın bir tanıktan ya da belgeden aktarıldığı izlenimi vermek', ['Anlatıcıyı tamamen gizlemek', 'Zamanı dondurmak', 'Betimlemeyi kaldırmak'], 'Bir belge ya da tanık göstermek gerçeklik izlenimini güçlendirir.'),
  ('Bir yazar, \'Çevre kirliliği çocukları etkiler; örneğin geçen yıl bir mahalledeki çocukların yüzde seksenine solunum rahatsızlığı teşhisi kondu.\' diyerek iddiayı bir olayla destekliyor. Bu yol hangisidir?', 'Örneklendirme', ['Tanımlama, kavramı kısaca belirleme', 'Karşılaştırma', 'Betimleme'], 'Genel bir iddiayı somut bir olayla desteklemek örneklendirmedir.'),
  ('\'Çünkü\', \'bu yüzden\', \'dolayısıyla\' gibi sözcüklerin sık kullanıldığı bir metinde hangi düşünceyi geliştirme yolu belirginleşir?', 'Neden–sonuç ilişkisi kurma', ['Betimleme', 'Tanımlama', 'Benzetme'], 'Bu bağlaçlar nedensellik ilişkisini kurar.'),
  ('\'Ancak\', \'oysa\', \'fakat\' gibi bağlaçlarla başlayan cümlelerin paragraftaki işlevi nedir?', 'Önceki düşünceye karşıtlık getirir', ['Önceki düşünceyi birebir tekrar eder', 'Yeni bir konu açar', 'Örnek verir'], 'Karşıtlık bildiren bağlaçlar düşünce akışını karşıt yöne çevirir.'),
  ('Bir paragrafın ana düşüncesini bulmak için aşağıdakilerden hangisi en uygun yoldur?', 'Paragrafın tamamını okuyup yazarın vermek istediği yargıyı belirlemek', ['Yalnız son sözcüğe bakmak', 'Yalnız ilk sözcüğü okumak', 'Sözcük sayısını saymak'], 'Ana düşünce metnin bütününden çıkarılan genel yargıdır.'),
  ('Bir metinde yazar, \'Ne yazık ki\' ifadesiyle kendi duygusunu belli ediyorsa bu ifade için hangisi söylenebilir?', 'Öznel anlatımı gösterir', ['Nesnel anlatımı gösterir', 'Tanımlamayı gösterir', 'Sayısal veriyi gösterir'], 'Duygu belirten ifadeler öznel anlatıma işaret eder.'),
  ('Bir paragraf, \'Önce... sonra... en sonunda...\' biçiminde sıralama sözcükleriyle ilerliyorsa bu paragraf için hangisi doğrudur?', 'Zamansal ya da işlemsel bir sıralama vardır.', ['Karşılaştırma vardır.', 'Tanık gösterme vardır.', 'Tümevarım vardır.'], 'Sıralama sözcükleri zamansal sıra kurar.'),
  ('Nesnel anlatımla ilgili aşağıdakilerden hangisi doğrudur?', 'Kanıtlanabilir, kişiden kişiye değişmeyen bilgilere dayanır.', ['Duygu ve beğeni bildirir.', 'Kişisel yorumdur.', 'Yalnız şiirde bulunur.'], 'Nesnel yargı gözlemle doğrulanabilir.'),
  ('\'Bu yıl on beş yeni roman yayımlandı; yine de çoğu beni heyecanlandırmadı.\' cümlesinde öznel ve nesnel yargılar nasıl dağılmıştır?', 'İlk bölüm nesnel, ikinci bölüm öznel', ['Her iki bölüm de yalnızca nesnel yargı içerir', 'Her iki bölüm de öznel', 'İlk bölüm öznel, ikinci bölüm nesnel'], 'Sayısal bilgi nesnel, heyecanlanmama öznel bir değerlendirmedir.'),
  ('Günlük ile anı arasındaki temel fark hangisidir?', 'Günlükte olaylar yaşandığı gün kaydedilir; anıda olaylar sonradan anlatılır.', ['Günlük yalnız şiirde, anı yalnız romanda bulunur.', 'Anıda tarih zorunludur, günlükte değildir.', 'Günlük bir başkasına yazılır, anı yazılmaz.'], 'Günlük olayın yaşandığı gün tarihle yazılır; anı ise geçmişten bakarak anlatılır.'),
  ('Mektubun diğer yazı türlerinden ayrıldığı en belirgin özellik hangisidir?', 'Belirli bir kişiye yöneltilmiş olması', ['Tarihî olay anlatması', 'Kanıtlarla yazılması', 'Duyguların hiç yer almaması'], 'Mektup belirli bir alıcıya yazılır.'),
  ('Resmî mektuplar ile özel mektuplar arasındaki fark için hangisi doğrudur?', 'Özel mektuplarda içten bir dil, resmî mektuplarda kalıplaşmış bir dil kullanılır.', ['Resmî mektuplar daha duygusaldır.', 'Özel mektuplarda tarih bulunmaz.', 'Resmî mektuplar yalnız şiirle yazılır.'], 'Özel mektup samimi, resmî mektup kalıplı ve ciddi bir dille yazılır.'),
  ('Bir günlüğün \'içtenlik\' özelliği taşımasının nedeni nedir?', 'Çoğu zaman başkaları için yazılmaması', ['Mutlaka yayımlanmak üzere ve başkaları için yazılması', 'Ünlü kişiler tarafından yazılması', 'Ağdalı bir dille yazılması'], 'Kişisel notlar çoğunlukla yayın amacı gütmediğinden içtendir.'),
  ('Bir biyografinin otobiyografiden ayrılan yönü, yazarın kişiyi hangi mesafeden anlatmasıdır?', 'Dışarıdan ve üçüncü kişi olarak', ['İçeriden, birinci kişi ağzıyla ve duygusal biçimde', 'Yalnızca şiirle', 'Yalnızca diyalogla'], 'Biyografi başkasının hayatını üçüncü kişi olarak anlatır.'),
  ('Gezi yazısının okura sunduğu en önemli katkı hangisidir?', 'Görülmemiş yerler hakkında gözlem ve izlenim', ['Bilimsel kanıtlar', 'Duygusal öykü', 'Dramatik çatışma'], 'Gezi yazısı yazarın gözlem ve izlenimlerini aktarır.'),
  ('Bir mektupta \'Sevgili dostum\' hitabı ve \'Saygılarımla\' ifadesiyle bitişin bulunması hangi özelliğe işaret eder?', 'Hitap ve bitiriş kalıpları taşıması', ['Kurmaca anlatı olması', 'Şiir olması', 'Makale olması'], 'Hitap ve bitiriş kalıpları mektuba özgü yapı öğeleridir.'),
  ('Sahne dekorunda bir odanın yalnız bir masa ve iki sandalyeyle gösterilmesi hangi yaklaşımı yansıtır?', 'Gösterimde yalınlık ve simgeselliğe dayanma', ['Aşırı gerçekçi dekor', 'Kronolojik düzensizlik', 'Prolog kullanma'], 'Az nesneyle bir mekânı çağrıştırmak yalın ve simgesel sahnelemeyi gösterir.'),
  ('Klasisizmde üç birlik kuralının amacı en çok hangisiydi?', 'Gerçeğe benzerlik ve olayların yoğunluğu', ['Seyirciyi şaşırtma', 'Mekân çeşitliliği', 'Zaman atlamaları'], 'Kuralın amacı olayların inandırıcı, yoğun ve düzenli sunulmasıdır.'),
  ('Trajedinin komediden ayrılan yönü aşağıdakilerden hangisidir?', 'Trajedi acıklı, komedi güldürücü bir olay işler.', ['Trajedi yalnızca nesirle, komedi yalnızca şiirle yazılır.', 'Trajedide halk kişileri, komedide kral kişileri yer alır.', 'Trajedi sahnelenmez, komedi sahnelenir.'], 'Trajedide korku ve acıma, komedide gülme duygusu amaçlanır.'),
  ('Karakter komedisi ile durum komedisi arasındaki fark hangisidir?', 'Karakter komedisi kişinin kusurundan, durum komedisi olayın yarattığı karışıklıktan doğar.', ['Karakter komedisi şiirle, durum komedisi nesirle yazılır.', 'Durum komedisi yalnızca çocuklar için yazılır.', 'Karakter komedisinde olay yoktur.'], 'Güldürü kimi zaman kişinin tipik kusurundan, kimi zaman olayların karışmasından doğar.'),
  ('Absürt tiyatronun temel özelliği aşağıdakilerden hangisidir?', 'Anlamsız ve çelişkili durumlarla insanın varoluş çıkmazını yansıtması', ['Ayrıntılı gerçekçi dekor kullanması', 'Olay örgüsünü sıkı bir nedensellikle kurması', 'Seyirciyi duygulandırıp ağlatması'], 'Absürt oyunlarda mantıksız diyalog ve durumlar varoluşun anlamsızlığını dile getirir.'),
  ('Bir romanın kahramanı çocukluktan yetişkinliğe geçerken yaşadığı olaylarla olgunlaşıyor. Roman hangi türe girer?', 'Gelişim romanı', ['Polisiye roman, soruşturma romanı', 'Bilimkurgu romanı, gelecek temalı eser', 'Mektup romanı, mektuplardan oluşan eser'], 'Kahramanın yetişme sürecini anlatan roman gelişim romanıdır.'),
  ('Maupassant tarzı hikâyelerde sürpriz sona doğru ilerleyen yapı hangi hikâye türünün özelliğidir?', 'Olay hikâyesi', ['Durum hikâyesi, kesit anlatan öykü', 'Anı, geçmişe dönük anlatı', 'Deneme, kişisel yazı'], 'Sürprizli sona dayalı yapı olay hikâyesinin tipik özelliğidir.'),
  ('Fantastik hikâyelerde olağanüstü olayların günlük yaşam içine sızması neye hizmet eder?', 'Gerçekle gerçek dışı arasındaki sınırı bulanıklaştırmaya', ['Okura kuru bilgi vermeye', 'Gözlemci bakış açısını uygulamaya', 'Kronolojik anlatımı güçlendirmeye'], 'Fantastik anlatıda olağanüstü olay gerçek dünyaya karışarak belirsizlik yaratır.'),
  ('Kısa hikâyenin romandan ayrılan özelliklerinden biri aşağıdakilerden hangisidir?', 'Az sayıda kişi ve tek bir olay ya da durum üzerinde yoğunlaşması', ['Çok sayıda kahramanı ve yan olayı barındırması', 'Kuşakları kapsayan uzun bir zaman dilimi kullanması', 'Birçok bölüme ayrılması zorunlu olması'], 'Hikâye, kısa sürede yoğun bir olay ya da durum anlatır.'),
  ('Aşağıdakilerden hangisi hikâye ile romanı ayırmada en geçerli ölçüttür?', 'Olayın kapsamı, kişi sayısı ve anlatı uzunluğu', ['Anlatıcının erkek ya da kadın olması', 'Yazarın yaşı', 'Kitabın kapağı'], 'Hikâye kısa, romandan daha dar kapsamlı ve az kişilidir.'),
  ('Bir yazarın siyasi bir olayı hayvan kahramanlarla alaya alması hangi iki türün birleşimini akla getirir?', 'Hiciv ve fabl', ['Ağıt ve methiye', 'Destan ve efsane', 'Roman ve günlük'], 'Hayvan kişilerle toplumu eleştirme hiciv ve fabl özelliğidir.'),
  ('Bir tiyatro oyununda kişilerin dış görünüşlerinin ve tavırlarının abartılarak güldürü yaratılması hangi öğeyle ilgilidir?', 'Karikatürize etme', ['Geriye dönüş, olayın geçmişe sarılarak anlatılması', 'Bilinç akışı', 'Epilog, oyunun sonundaki kapanış bölümü'], 'Abartılı çizim güldürüde karikatürizasyondur.'),
  ('Bir romanın epigrafı (sunuş sözü) olarak seçilen bir dize hangi işlevi taşır?', 'Eserin teması hakkında ipucu verir ve metinlerarası bağ kurar', ['Anlatıcıyı gizler', 'Kronolojiyi kurar', 'Mekânı tanıtır'], 'Epigraf, esere yön veren bir söz olarak okurda beklenti uyandırır.'),
  ('Aynı konuyu işleyen bir romanın, daha eski bir öyküyü yeniden yorumlayarak yazılması hangi kavramla ilişkilidir?', 'Yeniden yazım', ['Çerçeve öykü, iç içe anlatı', 'Betimleme, tasvir', 'Diyalog, konuşma'], 'Eski bir metni yeni bağlamda yeniden kurma yeniden yazımdır.'),
  ('\'Susmuş bütün kuşlar sabaha kadar\' dizesi kaç hecelidir ve duraklar nasıl dağılır?', '11 hece, 6+5', ['10 hece, 5+5', '11 hece, 5+6', '12 hece, 6+6'], 'Sus-muş bü-tün kuş-lar - sa-ba-ha ka-dar biçiminde dize on bir hecelidir ve 6+5 duraklıdır.'),
  ('Aşağıdaki dizelerden hangisi sekiz hecelidir?', 'Gece sessiz gündüz sessiz', ['Bu gece yine seni andım', 'Eski bir türkü söyler bülbül', 'Çocukluğum o eski sokakta kaldı'], 'Ge-ce ses-siz gün-düz ses-siz biçiminde sekiz hece vardır; diğer dizelerin hece sayısı farklıdır.'),
  ('\'Çocukluğum o eski sokakta kaldı\' dizesi kaç hecelidir?', '12', ['10', '11', '13'], 'Ço-cuk-lu-ğum o es-ki so-kak-ta kal-dı biçiminde on iki hece sayılır.'),
  ('Serbest ölçülü şiir için hangisi doğrudur?', 'Dize uzunluğu ve uyak düzeni şaire bağlıdır, iç ritim ön plandadır.', ['Hece sayısı sabittir.', 'Duraklar zorunludur.', 'Uyak mutlaka sarmal olur.'], 'Serbest ölçüde belli bir kalıp aranmaz, ritim şiirin iç yapısından doğar.'),
  ('Bir şiirde dizelerin hece sayısı birbirinden farklı olup uyak da bulunmuyorsa bu şiir için aşağıdakilerden hangisi söylenebilir?', 'Serbest nazımla yazılmıştır.', ['Hece ölçüsüyle yazılmıştır, hece sayısı sabittir.', 'Aruzla yazılmıştır.', 'Uyaklı koşma biçimindedir.'], 'Ölçü ve uyaktan bağımsız şiir serbest nazımdır.'),
  ('Şiirde ölçü ile uyak arasındaki fark nedir?', 'Ölçü dizelerin uzunluk düzenini, uyak dize sonlarındaki ses benzerliğini belirler.', ['Ölçü sesin benzerliği, uyak hece sayısıdır.', 'İkisi aynı şeydir.', 'Ölçü yalnız nesirde, uyak yalnız şiirde olur.'], 'Ölçü ritim ve uzunluk düzenidir; uyak ise ses benzerliğidir.'),
  ('\'Göz – yaz\' dize sonları arasındaki uyak türü için ne söylenebilir?', 'Yarım uyak', ['Tam uyak', 'Zengin uyak', 'Cinaslı uyak'], 'Yalnızca tek bir ünsüz benzerliği olduğundan yarım uyaktır.'),
  ('\'Gül – bül\' sözcüklerindeki uyağa hangi ad verilir?', 'Tam uyak', ['Yarım uyak', 'Zengin uyak', 'Cinaslı uyak'], 'Ünlü + ünsüz benzerliği (\'ül\') bulunduğu için tam uyaktır.'),
  ('\'Gözlerin gökyüzü gibi / Saçların gece gibi\' dizelerinde hangisi vardır?', 'Redif var, uyak yok', ['Uyak var, redif yok', 'Hem uyak hem redif var', 'Ne uyak ne redif var'], 'Dize sonlarında \'gibi\' tekrarlandığı için redif vardır; \'gökyüzü\' ile \'gece\' uyaklı değildir.'),
  ('Redif ile uyak arasındaki ilişkide hangisi doğrudur?', 'Redif uyağın arkasından gelen aynı sözcük ya da ek tekrarıdır.', ['Redif uyağın önünde yer alır.', 'Redif yalnız dize başlarında bulunur.', 'Uyak, redifin içinde yer alan bir unsurdur.'], 'Redif, uyaktan sonra tekrarlanan aynı sözcük ya da eklerdir.'),
  ('Uyağın şiire kattığı en önemli özellik hangisidir?', 'Müzikalite ve ahenk', ['Anlatım netliği', 'Zamanın belirlenmesi', 'Olay örgüsü'], 'Ses benzerliği şiire ahenk kazandırır.'),
  ('Aşağıdaki dörtlüklerden hangisi sarmal uyaklıdır? (Dize sonları verilmiştir.)', 'Dağ, yol, kol, bağ', ['Taş, bağ, taş, bağ', 'Yar, dar, yol, kol', 'Gül, bül, yol, yaz'], 'a-b-b-a düzenindeki dize sonları \'dağ, yol, kol, bağ\' biçiminde olandır.'),
  ('\'Gül gülü açtı gülşende / Bülbül bülbülü bastı kendinde\' gibi dizelerde ahenk ağırlıklı olarak hangi yolla sağlanır?', 'Ses ve sözcük tekrarlarıyla', ['Betimlemeyle', 'Diyalogla', 'Bilinç akışıyla'], 'Sözcüklerin yinelenmesi ahenk yaratır.'),
  ('Şiirde yumuşak ses duygusu uyandırmak isteyen bir şairin hangi sesleri sık kullanması beklenir?', 'l, m, n, ünlüler gibi akıcı sesler', ['k, t, p gibi sert ve patlayıcı sesler', 'Yalnız sert ve kesik ünsüzler', 'Hiçbir ünlü'], 'Akıcı sesler yumuşak, patlayıcı sesler sert bir ahenk yaratır.'),
  ('Dizelerde t, k, p sesleri sık yineleniyorsa bu durumun şiire katacağı etki hangisidir?', 'Sert ve vurucu bir ahenk', ['Yumuşak ve akıcı bir ahenk', 'Düz anlatım', 'Zaman atlaması'], 'Patlayıcı ünsüzler sert ve ritmik bir etki yaratır.'),
  ('Bir şiirde ünlem, soru ve devrik cümle kullanımının ahengi etkileme biçimi nedir?', 'Vurguyu ve söyleyiş ritmini değiştirerek', ['Şiirin ölçüsünü ortadan kaldırarak', 'Dizelerdeki sözcük sayısını sabit tutarak', 'Şiirin başlığını anlamsız kılarak'], 'Söz dizimi değişiklikleri okunuşta vurguyu ve ritmi etkiler.'),
  ('Beyit, dörtlük ve bent kavramlarının ortak yönü nedir?', 'Üçü de dize gruplarını adlandıran birimlerdir.', ['Üçü de yalnızca aruzla yazılan şiirlere özgüdür.', 'Üçü de uyaksız şiirlerin ayırt edici özelliğidir.', 'Üçü de yalnızca düzyazı metinlerinde bulunur.'], 'Bunların hepsi dize gruplarını adlandıran nazım birimleridir.'),
  ('Bir şiirde her bent beş dizeden oluşuyorsa bent için hangisi söylenebilir?', 'Beşlik (muhammes) niteliği taşır.', ['Dörtlüktür.', 'Beyittir.', 'Altılıktır.'], 'Beş dizelik birim beşliktir.'),
  ('Bir şiirde kaç beyit varsa toplam dize sayısı bunun kaç katıdır?', 'İki katı', ['Üç katı', 'Dört katı', 'Beş katı'], 'Beyit iki dizeden oluştuğundan dize sayısı beyit sayısının iki katıdır.'),
  ('Dramatik şiir türünde en belirgin özellik aşağıdakilerden hangisidir?', 'Şiirin diyalog ve çatışma içeren sahnelik yapıya sahip olması', ['Yalnız kişisel duygunun anlatılması', 'Kahramanlıkların anlatılması', 'Çobanların öven bir anlatım'], 'Dramatik şiirde sahnelenmeye elverişli çatışma ve konuşmalar vardır.'),
  ('Ağıt, bir yakının ölümü üzerine duyulan acıyı dile getirdiği için hangi şiir türüne yakındır?', 'Lirik şiir', ['Epik şiir, kahramanlık anlatan şiir', 'Pastoral şiir, kır yaşamı şiiri', 'Satirik şiir, alaycı şiir'], 'Kişisel acıyı dile getiren türler lirik şiirdir.'),
  ('Şiirde devrik cümle kullanımının başlıca amacı hangisidir?', 'Vurgu ve ahenk sağlamak', ['Anlamı gizlemek ve okuru yanıltmak', 'Ölçüyü bozmak ve ritmi ortadan kaldırmak', 'Zamanı atlayarak olayı hızlandırmak'], 'Devrik dizilim vurguyu değiştirir ve ahenge katkı sağlar.'),
  ('Şiir dilinde sözcüklerin sıra dışı dizilmesinin okur üzerindeki en belirgin etkisi nedir?', 'Dikkati çekmesi ve duygu yoğunluğunu artırması', ['Metni bilimsel kılması', 'Anlamı tamamen yok etmesi', 'Zamanı kesinleştirmesi'], 'Alışılmadık dizilim, okurun dikkatini çeker ve yoğun bir etki bırakır.'),
  ('\'Gönlüm bir deniz.\' dizesinde olduğu gibi ek-fiilin kullanılmaması anlatımda neye yol açar?', 'Daha yoğun ve kısa bir anlatıma', ['Metnin ağdalaşmasına ve anlaşılmaz hâle gelmesine', 'Sözdizimi bozukluğuna ve anlam karışıklığına', 'Aliterasyonun kalkmasına'], 'Ek-fiilin atılması anlatımı yoğunlaştırır ve akıcılığı artırır.'),
  ('Bir dizede özne gizli bırakılarak \'Yürüdü, durdu, baktı.\' diye yazılması hangi anlatım özelliğini gösterir?', 'Eksiltili anlatımla ekonomi sağlama', ['Devrik cümle kurma', 'Soru sorma', 'Yapılandırılmış paragraf'], 'Özneyi tekrar etmeden dizeyi kısa ve akıcı tutmak eksiltmedir.'),
  ('Şiirde bir sözcüğün ya da dizenin bilerek yinelenmesi okurda ne uyandırır?', 'Vurgu ve duygu yoğunluğu', ['Kronolojik ve doğrusal bir akış duygusu', 'Betimleme yoluyla ayrıntılı bir görüntü', 'Diyalog yoluyla canlı bir karşılıklı konuşma'], 'Yineleme duyguyu ve vurguyu artırır.'),
  ('\'Kuşlar uçtu, yaz gitti, sevgili de çekti ellerini.\' dizesindeki anlatımın etkisi için hangisi söylenebilir?', 'Art arda sıralanan kayıplar hüznü artırır.', ['Cümle kalıplaşmıştır.', 'Olay kronolojisi bozulmuştur.', 'Anlatıcı güvenilmezdir.'], 'Peş peşe gelen ayrılış öğeleri kaybın ağırlığını güçlendirir.'),
  ('Modernist romanın klasik gerçekçi romandan ayrılan başlıca özelliği hangisidir?', 'Bilinç akışı ve parçalanmış anlatımla iç dünyayı öne çıkarması', ['Kronolojik düzeni çok katı biçimde koruması', 'Anlatıcının her şeyi bilen sesine bağlı kalması', 'Toplumsal olayları dışarıdan belgelemesi'], 'Modernist roman, kronolojiyi kırıp iç dünyayı bilinç akışı gibi tekniklerle yansıtır.'),
  ('Postmodern anlatının tipik özelliklerinden biri aşağıdakilerden hangisidir?', 'Metinlerarasılık, parodi ve üstkurmaca kullanımı', ['Kuralları bozmayan klasik kurgu', 'Tek ve kesin bir doğru sunan anlatıcı', 'Mekân birliğine bağlılık'], 'Postmodern yazı, oyunbaz biçimde göndermeler, parodi ve üstkurmaca kullanır.'),
  ('Edebî bir metin toplumdaki yoksulluğu ve eşitsizliği gözlemleyerek, abartı olmaksızın belgesel bir bakışla anlatıyorsa bu metin hangi akımın özelliğini taşır?', 'Realizm', ['Romantizm, duygu ve hayal akımı', 'Sembolizm, imgeci akım', 'Sürrealizm, düş akımı'], 'Gözleme dayalı toplumsal anlatım realizmin özelliğidir.'),
  ('Bir eserin bazı bölümlerinin bilinçli olarak eksik bırakılıp noktalarla gösterilmesinin okura etkisi hangisidir?', 'Okurun boşlukları kendi yorumuyla doldurması', ['Metnin bilimsel olması', 'Anlatıcının güvenilirliği', 'Zamanın belirginleşmesi'], 'Eksiltme okuru yoruma çağırır.'),
  ('Bir yazar, sokakta duyduğu sözcükleri ve konuşma kalıplarını metnine taşıyor. Bu tercih en çok hangi etkiyi katar?', 'Doğallık ve gerçeklik hissi', ['Metnin ağdalaşması', 'Metnin bilimsel hâle gelmesi', 'Anlatıcının güvenilmez olması'], 'Konuşma dili metne canlılık ve inandırıcılık katar.'),
  ('Bir romanda her kişinin kendi şivesiyle konuşturulması hangi sonucu doğurur?', 'Kişilerin sosyal ve kültürel kimliğini belirginleştirir', ['Anlatıcıyı güvenilmez yapar', 'Zamanı belirsizleştirir', 'Mekânı kapalı kılar'], 'Ağız ve söyleyiş farkları kişileri toplumsal bağlamlarıyla tanıtır.'),
  ('Yazarın anlatıcıyla farklı bir dil kullanması, örneğin anlatıcı yalın, kahraman ise konuşma dilinde konuşuyorsa bu durum metinde hangi özelliği gösterir?', 'Çok sesli bir dil yapısını', ['Tek sesli ve yalnızca anlatıcı diline bağlı bir dil yapısını', 'Zamanın kısalmasını', 'Mekânın daralmasını'], 'Kişilerin kendi dilleriyle konuşması çok sesliliği gösterir.'),
  ('Ağdalı bir dille yazılmış eski bir metni günümüz Türkçesine çevirmenin en çok zorlandığı alan nedir?', 'Kalıplaşmış söz sanatlarının ve eski sözcüklerin karşılık bulması', ['Noktalama işaretleri', 'Satır uzunluğu', 'Sayfa düzeni'], 'Eski dilin çok anlamlı sözcükleri ve söz sanatları aktarmayı güçleştirir.'),
  ('Bir yazar belirli bir sözcüğü bilerek tekrarlayıp başka eş anlamlıları kullanmaktan kaçınıyorsa bu tercih neye işaret eder?', 'Bilinçli bir vurgu ve üslup tercihine', ['Dil bilgisi hatasına', 'Bilgi eksikliğine', 'Zaman atlamasına'], 'Bilinçli yineleme üslubun bir parçası olarak anlamı vurgular.'),
  ('Uzun, bağlaçlarla birbirine eklemlenmiş cümlelerin sık kullanıldığı bir metin okura hangi etkiyi verir?', 'Kesintisiz bir akış ve nefes alma güçlüğü', ['Kısa, vurgulu bir etki', 'Duraksayan bir hız', 'Katı bir bilimsel sözdizimi'], 'Uzun, bağlaçlı cümleler akışı sürekli kılar ve okuru soluksuz bırakır.'),
  ('Kısa ve kesik cümlelerin art arda kullanılması metinde hangi etkiyi yaratır?', 'Hızlı tempo ve gerilim', ['Ağır ve melankolik tempo', 'Zamanın durması', 'Bilimsel nesnellik'], 'Kısa cümleler hızlı ve gergin bir anlatı kurar.'),
  ('Sanatçı ile üslup arasındaki ilişkiyi en iyi açıklayan söz hangisidir?', 'Üslup, sanatçının dilsel kimliğidir', ['Üslup, yazarın yaşıyla belirlenen bir özelliktir', 'Üslup, kitabın sayfa sayısına bağlı bir niteliktir', 'Üslup, yazarın mesleğinden doğan bir kavramdır'], 'Her yazarın dili kullanışı onun üslubunu oluşturur.'),
  ('Bir eleştirmen, bir romandaki kahramanın çocukluk travmalarını bilinçdışı çatışmalarla açıklıyor. Bu yaklaşım hangisidir?', 'Psikanalitik eleştiri', ['Marksist eleştiri, sınıf odaklı yöntem', 'Yeni Eleştiri, metin merkezli yöntem', 'Biyografik eleştiri, yazar yaşamına dayalı yöntem'], 'Bilinçdışı çatışmaları inceleyen yöntem psikanalitik eleştiridir.'),
  ('Okur merkezli bir yaklaşıma göre aynı metni iki farklı okurun farklı yorumlaması neyi gösterir?', 'Anlamın okurla birlikte oluştuğunu', ['Metnin hatalı yazıldığını ve yeniden düzeltilmesi gerektiğini', 'Yorumlardan yalnız birinin doğru, diğerinin yanlış olduğunu', 'Anlamın tek ve kesin olduğunu'], 'Okur merkezli kurama göre anlam, metin ile okurun karşılaşmasında oluşur.'),
  ('İyi bir edebî eleştirinin ayırt edici ölçütü aşağıdakilerden hangisidir?', 'Yargılarını metinden örneklerle ve gerekçelerle desteklemesi', ['Yalnızca beğenilen eserleri övmesi', 'Yalnızca yazarın kişiliğine odaklanması', 'Yalnızca eserin satış sayısını esas alması'], 'Gerekçeli ve örnekle desteklenen eleştiri nesnel değerlendirme sunar.'),
  ('Bir eleştirmen, eseri hiçbir gerekçe göstermeden \'çok başarısız\' diye niteliyorsa bu eleştiri için hangisi söylenebilir?', 'Öznel ve gerekçesiz bir yargıdır.', ['Nesnel ve kanıtlı bir yargıdır.', 'Bilimsel ve kanıta dayalı bir inceleme olması', 'Yapısalcı bir çözümlemedir.'], 'Gerekçe gösterilmeyen yargı öznel kalır.'),
  ('\'Toplum için sanat\' anlayışını savunan bir yazarın eserinde en çok hangi özelliği beklersiniz?', 'Toplumsal sorunlara duyarlılık ve ileti', ['Biçimsel kusursuzluk kaygısıyla toplumsal temalardan kaçınma', 'Kişisel iç dünyaya kapanma', 'Dil oyunlarından ibaret olma'], 'Toplumcu anlayış, edebiyatın toplumsal sorunlara eğilmesini ister.'),
  ('Bir şiirin yazıldığı dönemin toplumsal koşullarına göre farklı anlamlar kazanması için ne söylenebilir?', 'Edebî eser tarihsel bağlama göre yeniden yorumlanabilir.', ['Edebî eserin anlamı değişmez.', 'Eser yalnız yazıldığı dönemde anlaşılır.', 'Eserin toplumla ilişkisi yoktur.'], 'Edebî eserler farklı dönemlerde farklı biçimlerde yorumlanabilir.'),
  ('Bir romanın toplumsal gerçekliği yansıttığı söylenirken \'yansıtma\' sözüyle neyin kastedildiği en doğru hangisidir?', 'Toplumsal olguların kurmaca bir düzenle sunulması', ['Toplumsal olguların fotoğraf gibi birebir aktarılması', 'Toplumun bütün tarihini içermesi', 'Yalnız yazarın kendi ailesini anlatması'], 'Roman gerçeği kurmaca bir çerçevede yeniden kurar.'),
  ('Edebiyatın toplum üzerindeki en kalıcı etkisi aşağıdakilerden hangisi olarak görülür?', 'İnsanların duygu, düşünce ve bakışlarını dönüştürmesi', ['Ekonomik üretimi artırması', 'Hava koşullarını değiştirmesi', 'Matematik başarısını yükseltmesi'], 'Edebiyat okurun algısını ve duyarlılığını biçimlendirir.'),
  ('Bir yazarın baskı rejimi altında doğrudan eleştiri yerine alegori ve simge kullanmasının nedeni nedir?', 'Sansürden kaçınıp eleştiriyi örtük biçimde ulaştırmak', ['Dili sadeleştirmek', 'Zamanı kısaltmak', 'Anlatıcıyı değiştirmek'], 'Baskı ortamında dolaylı anlatım yazara eleştiri yapma imkânı verir.'),
  ('Sanatın çağının ruhunu yansıtması gerektiğini savunan bir eleştirmen hangi tür eser bekler?', 'Dönemin sorunlarını ve duyarlılıklarını yansıtan eser', ['Dönemin dışında kalan bir kurgu', 'Tamamen geçmişi anlatan eser', 'Tamamen gelecekten bahseden eser'], 'Çağın ruhunu yansıtma talebi, dönemin sorunlarına duyarlı eser ister.'),
  ('\'Şehrin en büyük müzesine tam üç saat kuyrukta bekledik; içeri girdiğimizde yalnız bir kapıyı gösterip bizi sıkıştırdılar. Ne kadar da muhteşem bir organizasyon!\' Son cümlenin tonu hangisidir?', 'İroni', ['Hayranlık', 'Mutlu coşku', 'Sakin onay'], 'Hoşnutsuz bir durumu \'muhteşem\' diyerek övmek ironik bir tondur.'),
  ('\'Bu kadar yıl çalıştım, ter döktüm, hakkımı gasp ettiler; artık sessiz kalmayacağım, herkes sesimi duyacak!\' Bu sözlerin tonu için hangisi doğrudur?', 'Öfkeli ve başkaldıran', ['Nostaljik, geçmişi özleyen ve yumuşak', 'Alaycı ve soğuk', 'Sakin ve kabullenici'], 'Hakkın gasp edildiği duygusu ve sesini duyurma kararlılığı öfkeli, başkaldıran bir tondur.'),
  ('\'Hayat bazen bir kapıyı kapatır, ama unutma ki başka bir kapıyı mutlaka açar.\' Cümlenin ton ve amacı hangisidir?', 'Teselli ve umut aşılama', ['Alaycı eleştiri ve acımasız bir yergi', 'Kesin bir tehdit', 'Nesnel bilgi aktarma'], 'Zorluk karşısında umudu vurgulayan söz teselli amaçlıdır.'),
  ('\'Ölçüleri hep o ustadan alırdı; usta ölünce de bütün kasaba aynı terzinin önünde sustu.\' Bu cümledeki sessizlik neyi yansıtır?', 'Yasın ve kaybın ortak hissi', ['Kasaba halkının öfkesini', 'Kasabanın yeni terziye duyduğu hayranlığı', 'Hiçbir duyguyu'], 'Ustanın ölümü karşısındaki suskunluk ortak bir yas duygusunu gösterir.'),
  ('\'Yaşlı adam, bahçedeki sedirde oturup uzaklara baktı; gözlerinde yıllardır birikmiş bir yorgunluk vardı.\' Bu cümlenin yarattığı genel duygu hangisidir?', 'Melankoli', ['Neşeli coşku', 'Öfkeli isyan', 'Alaycı hafiflik'], 'Uzaklara bakış ve birikmiş yorgunluk melankolik bir hava kurar.'),
  ('\'Müdür bey yine sınıfa daldı: öğretmenlere akıl vermekten, öğrencileri azarlamaktan başka hiçbir işe yaramayan, ama kendini okulun yıldızı sanan zavallı!\' Bu cümlede anlatıcının müdüre karşı tutumu hangisidir?', 'Alaycı ve aşağılayıcı', ['Saygılı ve övücü', 'Hayran ve teşvik edici', 'Kayıtsız ve sakin'], 'Kullanılan sıfatlar ve \'zavallı\' sözü alaycı bir bakışı açığa çıkarır.'),
  ('\'Çocuk, annesinin gittiği yoldan gözünü ayırmadan bekledi; sabah olunca gelir diye, öğle olunca belki akşam diye.\' Bu cümledeki bekleyişin etkisi nedir?', 'Umut ile kaygının birlikteliği', ['Kesin ve acı bir hayal kırıklığı', 'Nesnel bir bilgi aktarımı', 'Alaycı ve umursamaz bir bakış'], 'Bekleyişin her an ertelenmesi umutla kaygıyı iç içe geçirir.'),
  ('\'Savaşın bitmesine bir hafta kalmıştı; ama köyün çocukları hâlâ her akşam kapının önüne çıkıp dönmeyecek babalarının yolunu gözlüyordu.\' Bu cümledeki duygu için hangisi söylenebilir?', 'Acı bir hüzün ve kayıp duygusu', ['Neşeli bir umut', 'Alaycı bir bakış', 'Kesin bir rahatlama'], 'Dönmeyecek babaların beklenmesi yoğun bir kayıp ve hüzün duygusu yaratır.'),
  ('\'Yağmur dinince toprağın kokusu yükseldi; kediler çatıya çıkıp tüylerini yaladı, sokak yeniden nefes aldı.\' Bu parçanın ağırlıklı duygusu hangisidir?', 'Dinginlik ve yenilenme', ['Panik ve kaygıyla dolu bir telaş', 'Öfke ve nefret', 'Alay ve küçümseme taşıyan bir hava'], 'Yağmur sonrası toprağın kokusu ve sokağın nefes alması huzur ve yenilenme duygusu verir.'),
  ('Aşağıdaki cümlelerin hangisinde anlatıcının tutumu mizahi ve hafif bir alaycılık içerir?', 'Kediye \'Sayın Komiser\' diye hitap edip masasına oturttu.', ['Bu sabah hava yağmurluydu.', 'Toplantı saat onda başladı.', 'Adam, trene bindi ve pencereden dışarı baktı.'], 'Kediye komiser denmesi gülünç bir durum yaratarak alaycı bir mizah katar.'),
  ('\'Yaşadığım şehri sevmedim hiç; sevmeyi bilmedim, belki de kendimi sevmeyi öğrenememişimdir.\' Bu cümlede kendini sorgulayan hangi ses vardır?', 'İçe dönük ve özeleştirel bir ses', ['Dışarıdan bakan nesnel bir ses', 'Alaycı, acımasız ve dışarıdan bakan bir ses', 'Neşeli ve coşkulu bir ses'], 'Kişi kendi eksikliğini düşündüğü için ses içe dönük ve özeleştiricidir.'),
  ('\'Dün öğleden sonra şehrin kuzeyindeki sanayi sitesinde çıkan yangın, itfaiye ekiplerinin müdahalesiyle üç saatte kontrol altına alındı. Can kaybı yaşanmadığı bildirildi.\' Bu parça hangi türe benzer?', 'Haber', ['Deneme, kişisel yorum yazısı', 'Anı, yaşanmış kişisel anlatı', 'Şiir, dizelerle yazılmış metin'], 'Güncel olayı nesnel ve kısaca bildiren yazı haberdir.'),
  ('Aşağıdaki numaralı cümlelerden oluşan paragrafta konu bütünlüğünü bozan cümle kaçıncıdır? (1) Kütüphane, okuma alışkanlığını artıran bir mekândır. (2) Çocuklar burada kitapla tanışır. (3) Ayrıca kütüphanede çalışanlar sabah erkenden kahvaltı yapar. (4) Yetişkinler de araştırma yapmak için buraya gelir.', 'Üçüncü cümle', ['Birinci cümle, genel yargıyı bildiren giriş', 'İkinci cümle, çocukların kitapla tanışmasını anlatan', 'Dördüncü cümle, yetişkinlerin araştırmasını bildiren'], 'Kahvaltı bilgisi, paragrafın konusu olan kütüphanenin okuma işleviyle ilgisizdir.'),
  ('\'Kitap okumanın faydaları saymakla bitmez. Hem dil gelişir, hem hayal gücü zenginleşir, hem de empati yeteneği artar.\' Bu iki cümle arasındaki ilişkiyi en iyi hangisi açıklar?', 'İkinci cümle, birinci cümledeki genel yargıyı örneklendirir.', ['İkinci cümle birinciyle çelişir.', 'İkinci cümle birinciyi yineler.', 'İkinci cümle sonuç bildirir.'], 'İkinci cümle faydaların neler olduğunu sıralayarak genel yargıyı destekler.'),
  ('\'Zaten uzun süredir çalışıyordu; ancak sonuç alamadı. Bu nedenle yöntemini değiştirdi.\' Parçada \'ancak\' ve \'bu nedenle\' bağlaçlarının işlevi nedir?', 'Karşıtlık ve sonuç ilişkisi kurar', ['Örneklendirme yapar', 'Benzetme yapar', 'Tanım verir'], '\'Ancak\' karşıtlık, \'bu nedenle\' sonuç belirtir.'),
  ('Bir metnin başlığı seçilirken aşağıdakilerden hangisi göz önünde bulundurulmalıdır?', 'Metnin konusunu ve ana düşüncesini yansıtması', ['Metnin ilk sözcüğüyle birebir aynı olması ve tekrar etmesi', 'Metnin son sözcüğünü içermesi', 'Metinde hiç geçmeyen ve konuyla ilgisiz bir kavram olması'], 'İyi başlık, metnin konusunu ve vermek istediği ana fikri yansıtır.'),
  ('Bir metnin giriş bölümünde genellikle neler yer alır?', 'Konunun tanıtılması ve ilgi çekici bir başlangıç', ['Metnin sonucu', 'Metnin kaynakçası', 'Metindeki tüm örneklerin toplamı'], 'Giriş, konuyu açar ve okurun ilgisini çekmeyi hedefler.'),
  ('Bir metnin sonuç bölümünde hangisi beklenir?', 'Ana düşüncenin toparlanması ve vurgulanması', ['Yeni bir konunun açılması', 'Konunun hiç ele alınmaması', 'Yalnız örneklerin listesi'], 'Sonuç, ana düşünceyi derleyip toplar.'),
  ('\'Ağladı; hayır, ağlamadı, yangın yerine döndü yüreği.\' ifadesinde hangi söz sanatı vardır?', 'Rücu', ['Cinas, sesteş sözcük kullanımı', 'Tevriye, iki anlamlı söz kullanımı', 'Tenasüp, anlamca ilişkili sözcükler'], 'Söylenen \'ağladı\' sözünden dönülüp daha güçlü bir ifade getirilmiştir.'),
  ('Bir şairin ölen arkadaşına seslenip \'Ey dost, sen nerelerdesin?\' diyerek ona konuşması hangi sanatların birleşimini gösterir?', 'Nida ve istifham', ['Tezat ve tevriye, karşıtlık ve çift anlam kullanımı', 'Cinas ve tenasüp', 'Rücu ve tedric'], 'Seslenme ve soru söz sanatlarının birlikte kullanıldığını gösterir.'),
  ('Bir sonenin son iki dizesinin genellikle ne işlevi vardır?', 'Şiirin sonuç ya da özet düşüncesini vermek', ['Şiirin başlığını açıklamak', 'Uyak düzenini bozmak', 'Anlatıcıyı değiştirmek'], 'Soneler genellikle son dizelerinde bir sonuç ya da dönüş bölümü taşır.'),
  ('\'Hiçbir şey bilmediğim bir kente varmıştım. Çantamı bırakıp pencereden baktım; sokaktaki insanlar dilimi konuşmuyordu, ama gözlerinde bir tanıdıklık vardı.\' Bu parçanın bakış açısı ve odaklaması hangisidir?', 'Kahraman bakış açısı, içsel odaklama', ['İlahi bakış açısı, sıfır odaklama', 'Gözlemci bakış açısı, dışsal odaklama', 'Çoğul bakış açısı, çok anlatıcılı yapı'], 'Birinci kişi ve yalnız kahramanın algısı kullanıldığı için kahraman bakış açısı ve içsel odaklama vardır.'),
  ('\'Mehmet kapıyı çekip çıktı. Aynı anda annesi mutfakta, oğlunun bir daha dönmeyeceğini yüreğinde hissediyor, ama bunu kimseye söylemiyordu.\' Bu parça için hangisi söylenebilir?', 'Anlatıcı birden çok kişinin iç dünyasını bildiği için ilahi bakış açısı kullanılmıştır.', ['Gözlemci bakış açısı kullanılmıştır.', 'Kahraman bakış açısı kullanılmıştır.', 'İkinci kişi anlatıcı vardır.'], 'Anlatıcı annenin hissini ve Mehmet\'in hareketini aynı anda bildiği için ilahi bakış açısı vardır.'),
  ('\'Genç kadın masaya oturdu, çantasından bir zarf çıkarıp açtı, okudu ve hiçbir şey demeden zarfı yırttı.\' Bu parçanın anlatıcısı için hangisi söylenebilir?', 'Dışarıdan gördüklerini aktaran, iç dünyaya girmeyen bir anlatıcıdır.', ['Kadının içinden geçenleri bilen bir anlatıcıdır.', 'Kendini \'ben\' diye tanıtan kahraman anlatıcıdır.', 'Okurla alay eden güvenilmez anlatıcıdır.'], 'Kadının duygusu verilmiyor, yalnız davranışları anlatılıyor; gözlemci bakış açısıdır.'),
  ('\'Ben, yıllar önce o evden çıkarken kapıyı kilitlemeyi unuttuğumu sanıyordum; oysa annem arkamdan sessizce kilitlemişti.\' Bu cümlede anlatıcının farkındalığı için ne söylenebilir?', 'Anlatıcı yıllar sonra geriye bakıp kendi eski yanılgısını düzeltmektedir.', ['Anlatıcı olayları o an yaşamaktadır.', 'Anlatıcı yalnız dışarıdan gözlem yapmaktadır.', 'Anlatıcı hiçbir şeyi hatırlamamaktadır.'], 'Anlatıcı, geçmiş yanılgısını sonradan fark ettiği için yetişkin anlatıcı ile çocuk \'ben\' arasında bir ayrım vardır.'),
  ('\'Köylüler, yağmur dualarına çıkarken göğe baktı. Her biri, yağmurun gelmesini diliyordu; kimi çocukları için, kimi tarlası için, kimi yalnızca yeniden gülebilmek için.\' Bu parçanın bakış açısı hangisidir?', 'İlahi bakış açısı', ['Kahraman bakış açısı', 'Gözlemci bakış açısı', 'İkinci kişi bakış açısı'], 'Anlatıcı herkesin içinden geçeni bildiği için ilahi bakış açısıdır.'),
  ('Bir yazar, aynı cinayet olayını önce şüphelinin, sonra dedektifin, en son tanığın ağzından anlatıyor. Bu yapının okura sağladığı en önemli katkı nedir?', 'Olaya farklı bakışları karşılaştırma ve gerçeği sorgulama fırsatı', ['Kronolojik sıranın korunması', 'Anlatıcının tek ve kesin hükmü', 'Mekânın daralması'], 'Çoklu bakış açısı okuru gerçeğin göreli olduğunu fark etmeye iter.'),
  ('Bir öyküde bakış açısı kahramandan gözlemciye geçiyorsa bu geçişin yarattığı olası etki nedir?', 'Kahramanın iç dünyasından dışarıdan gözlemeye geçerek mesafe ve gizem yaratmak', ['Zamanın geriye sarılması', 'Mekânın küçülmesi', 'Diyalogların silinmesi'], 'İç dünyadan dış gözleme geçiş, okura mesafe ve gizem verir.'),
  ('\'Sen bu sabah yine geç kalıyorsun; çantanı alıyor, merdivenleri koşarak iniyorsun ve kimseyle konuşmak istemiyorsun.\' Bu parçadaki anlatım için hangisi söylenebilir?', 'İkinci tekil kişili bir anlatım söz konusudur.', ['Üçüncü kişili ilahi bakış açısıyla yazılmış bir anlatım vardır.', 'Birinci çoğul kişiyle kurulmuş toplu bir anlatım vardır.', 'Üçüncü kişili gözlemci bakış açısı vardır.'], '\'Sen\' ile seslenen anlatım ikinci tekil kişi kullanır.'),
  ('Bir anlatıcının \'Evet, kuşkusuz; hepimiz biliyoruz ki o bir hırsızdı\' demesi, bunu savunacak bir kanıt göstermemesi hangi olasılığı gündeme getirir?', 'Anlatıcının güvenilmez ve taraflı olması', ['Anlatıcının çocuk olması ve olayı yanlış anlaması', 'Anlatıcının yalnız betimleme yapması', 'Anlatıcının sıfır odaklama kullanması'], 'Kanıtsız kesin yargı, anlatıcının güvenilirliğini sorgulatır.'),
  ('\'Kahve kokusu... babam... eski bahçe... bir araba sesi... annemin elleri... denizde bir kayık... hep aynı gün müydü...\' Bu parça için hangisi söylenebilir?', 'Bilinç akışı tekniği kullanılmıştır.', ['Kronolojik, olay sırasına dayanan bir öykü anlatılmıştır.', 'Bilimsel bir tanım yapılmıştır.', 'Resmî bir yazışma örneğidir.'], 'Zihnin düzensiz çağrışımlarının kesintisiz verilmesi bilinç akışıdır.'),
  ('\'Nasıl bir insan sorarsan bana, derim ki, yağmurdan sonra çıkan güneş gibi biri,\' diyor yaşlı kadın; oysa gözleri bir an boşluğa kayıyor. Bu parçada karşılıklı konuşma olmadığı hâlde anlatımda hangi teknik vardır?', 'Doğrudan aktarmayla birlikte betimleme', ['Sadece iç monolog', 'Sadece bilinç akışı', 'Sadece ileri sıçrama'], 'Konuşma doğrudan aktarılıp kişinin bakışı ayrıca betimlenmiştir.'),
  ('\'Sokaklar çocuk sesleriyle uyanır, / Bu şehir her sabah yeniden doğar.\' dizelerinde şehre hangi özellik yüklenmiştir?', 'İnsanî (canlı) bir özellik', ['Soyut bir kavram niteliği', 'Ölçüsel bir nitelik, sayıyla belirlenen özellik', 'Bilimsel ve laboratuvarda ölçülen bir özellik'], 'Şehrin uyanması ve doğması canlı bir varlığa özgü nitelikleri yansıtır.'),
  ('\'Ben ise dünün yorgunluğunu taşırım.\' dizesinin sezdirdiği ruh hâli hangisidir?', 'Bitkinlik ve geçmişin ağırlığı', ['Neşe ve coşku', 'Öfke ve isyan', 'Kayıtsızlık'], '\'Dünün yorgunluğunu taşımak\' geçmişin ağırlığını ve bitkinliği anlatır.'),
  ('\'Kuşlar göçtü, sen gittin, / Boş kaldı yuvamız, boş kaldı yürek.\' dizelerinin anlatımındaki yinelemenin etkisi nedir?', 'Boşluk ve kaybı vurgulamak', ['Bilimsel kesinlik ve nesnel bir anlatım sağlamak', 'Mizah yaratmak', 'Zamanı atlamak'], '\'Boş kaldı\' tekrarı kaybın boşluğunu vurgular.'),
  ('\'Deniz bir ayna gibi, / Göğü yutmuş mavi sessizlik.\' dizelerindeki ana imge hangi duyuya seslenir?', 'Görme', ['Tat alma', 'Koklama', 'İşitme'], 'Ayna benzetmesi ve mavi sessizlik yalnızca görsel bir imgedir.'),
  ('\'Yağmurun sesi pencerede bir ninni, / Bütün dünya göz kapaklarına iner.\' dizelerinin atmosferi hangisidir?', 'Dingin ve uyutucu', ['Gergin ve kaygılı', 'Öfkeli ve gürültülü', 'Neşeli ve hareketli'], 'Ninni ve göz kapaklarına inen dünya huzurlu, uyutucu bir hava kurar.'),
  ('Bir şiirde kuru dallar, boş sokaklar, kapanmış pencereler ve soğuk bir rüzgâr betimleniyorsa bu imgelerin birlikte oluşturduğu atmosfer hangisidir?', 'Hüzün ve yalnızlık', ['Coşku ve neşe dolu, hareketli bir bayram havası', 'Öfke ve isyan', 'Zafer ve gurur dolu, kahramanlık duygusu taşıyan bir hava'], 'Boşluk, soğukluk ve kapalılık yalnızlık ve hüzün atmosferi oluşturur.'),
  ('Bir şairin kullandığı \'Bütün evler birer göz, / Bütün sokaklar birer ses\' dizelerinde hangi yöntem baskındır?', 'Benzetme yoluyla çevreyi canlandırma', ['Bilimsel tanım', 'Tarihî belge aktarımı', 'Resmî dil kullanımı'], 'Evlerin göze, sokakların sese benzetilmesi bir canlandırma yöntemidir.'),
  ('\'Zaman bir nehir; ben kıyısında bekleyen bir yolcu.\' dizesinde anlatılan duygu hangisidir?', 'Akıp giden zaman karşısında çaresiz bekleyiş', ['Zafer coşkusu', 'Öfke nöbeti', 'Alaycı eğlence'], 'Zamanın nehir, kişinin yolcu olarak anlatılması çaresiz bekleyişi yansıtır.'),
  ('\'Dünya bir han, ben bir misafir; / Her sabah çıkarım yola, akşam yine han.\' dizelerinin temel teması aşağıdakilerden hangisidir?', 'Dünyanın geçiciliği', ['Savaşın yıkımı ve ölümün kaçınılmazlığı', 'Doğa sevgisi', 'Ekonomik sıkıntı'], 'Dünyanın han, insanın misafir olarak sunulması geçicilik temasını verir.'),
  ('Bir şiirde \'umut\' sözcüğü hiç geçmediği hâlde tomurcuklanan dallar, açan pencereler ve uzayan günler betimleniyorsa şiirin duygu tonu için hangisi söylenebilir?', 'Umutlu ve yenilenme dolu', ['Karamsar ve yıkıcı, umutsuzluk dolu bir ton', 'Alaycı ve soğuk, mesafeli bir ton', 'Sert ve tehditkâr, korkutucu bir ton'], 'Tomurcuk, açan pencereler ve uzayan günler yenilenme ve umut çağrıştırır.'),
  ('Kurmaca bir metinde \'gerçeğe benzerlik\' ile \'gerçek olma\' arasındaki fark nedir?', 'Gerçeğe benzer metin inandırıcıdır ama olaylar yaşanmış olmak zorunda değildir.', ['İkisi aynı anlama gelir.', 'Gerçeğe benzer metin yalnız belgelere dayanır.', 'Gerçek olan metin hiçbir zaman kurmaca sayılmaz.'], 'Okurda inandırıcılık yaratmak gerçeğe benzerliktir; olayın yaşanmış olması gerekmez.'),
  ('Bir yazarın kendi yaşamından esinlenerek yazdığı ama kişileri ve olayları değiştirdiği bir roman için aşağıdakilerden hangisi doğrudur?', 'Otobiyografik ögeler taşıyan bir kurmacadır.', ['Kesin bir biyografidir.', 'Gerçek bir günlüktür.', 'Resmî bir belgedir.'], 'Yaşamdan esinlenip kurguyla dönüştürülmüş eser otobiyografik ögeli kurmacadır.'),
  ('Bir edebî eserin \'başyapıt\' sayılması için en çok hangi ölçüt öne çıkar?', 'Zamanın ötesinde etkisini sürdürmesi ve çok katmanlı yorumlara açık olması', ['Çok sayıda baskı yapması', 'Yazarın ünlü olması', 'Kitabın hacminin büyük olması'], 'Başyapıtlar farklı çağlarda okunup yeniden yorumlanabildikleri için kalıcıdır.'),
  ('Edebiyatın bilimden farkı için aşağıdakilerden hangisi doğrudur?', 'Edebiyat duygu ve hayal gücüyle, bilim kanıt ve gözlemle ilerler.', ['Edebiyat kanıta, bilim duyguya dayanır.', 'Edebiyat yalnız doğruyu, bilim yalnız yanlışı anlatır.', 'İkisinin dili aynıdır.'], 'Edebî metinler estetik ve çok anlamlıdır; bilimsel metinler doğrulanabilir ve kesindir.'),
  ('Bir edebî eserin \'çok anlamlılığı\' neyi ifade eder?', 'Metnin farklı okuyucular tarafından birden fazla biçimde yorumlanabilmesini', ['Metnin birçok dile çevrilmesini', 'Metnin çok sayıda yazara ait olmasını', 'Metnin çok uzun olmasını'], 'Çok anlamlılık, edebî dilin okura yorum alanı bırakmasıdır.'),
  ('\'Kasabanın saatçisi, yıllarca herkesin saatini ayarladı; ama kendi saati hep geriydi. Bir gün sorduklarında, "Başkalarının zamanıyla uğraşırken kendiminkini unuttum," dedi.\' Bu parçada vurgulanan temel düşünce hangisidir?', 'İnsan başkaları için çalışırken kendi yaşamını ihmal edebilir.', ['Saatçilik zor bir meslektir.', 'Kasabalıların saatleri hep geridir.', 'Zaman her zaman hızlı akar.'], 'Saatçinin sözü, başkalarına adanan emeğin kendi yaşamı ihmal ettirdiğini sezdirir.'),
  ('\'Kitaplığın en alt rafında duran o eski roman, yıllarca kimsenin elini sürmediği için tozlanmıştı; ama biri açtığı an, toz bile bir hikâyeye dönüştü.\' Bu cümlenin sezdirdiği düşünce hangisidir?', 'Değer görmeyen şeyler, ilgi gösterildiğinde anlam kazanabilir.', ['Kitaplar temizlenmelidir.', 'Eski romanlar kötüdür.', 'Kitaplıklar alt rafta tutulmalıdır.'], 'Toz bile hikâyeye dönüşünce, ilgi gören şeyin anlam kazandığı vurgulanır.'),
  ('\'Köprüyü yapan usta, köprü bitince nehrin öbür yakasına hiç geçmedi; çünkü onun için önemli olan karşıya varmak değil, karşıya varılabilir kılmaktı.\' Bu parçadan çıkarılabilecek yargı hangisidir?', 'Emek veren kişi için asıl değer, başkalarına yol açmaktır.', ['Köprüler tehlikelidir.', 'Ustalar nehri sevmez.', 'Karşıya geçmek gereksizdir.'], 'Usta için önemli olan, kendi varışı değil başkalarının geçişini sağlamaktır.'),
  ('\'Bir ağaç dikmeden önce gölgesinde dinleneceğini sanma; kimi ağaç, ancak torunlarının serinliği için dikilir.\' Bu cümlenin ana düşüncesi hangisidir?', 'Bazı emeklerin karşılığı sonraki kuşaklara kalır.', ['Ağaç dikmek gereksizdir.', 'Gölgede dinlenmek en iyisidir.', 'Torunlar ağaç sever.'], 'Sözün asıl vurgusu, emeğin faydasının gelecek kuşaklarca görüleceğidir.'),
  ('\'Bu kentte kuralları herkes bilir; ama kuralları uygulayanlar da, çiğneyenler de kendini haklı çıkarmak için aynı kuralı gösterir.\' Bu cümlenin eleştirdiği durum hangisidir?', 'Kuralların çıkara göre yorumlanması', ['Kuralların bilinmemesi ve öğretilmemesi', 'Kuralların çok fazla olması ve karmaşıklığı', 'Kuralların hiç değişmemesi ve katı olması'], 'Cümle, aynı kuralın farklı tarafların işine gelecek biçimde yorumlandığını eleştirir.'),
  ('Bir yazar, anlattığı kahramanın kötülüklerini hiçbir yorum eklemeden sıralıyor. Okur bu kişiyi sonunda hor görüyorsa yazarın bu yoldan vermek istediği düşünce nasıl ortaya çıkmıştır?', 'Yargı açıkça söylenmeden, olaylar ve davranışlar yoluyla sezdirilmiştir.', ['Yazar yargısını doğrudan bildirmiştir.', 'Bir tanım yapmıştır.', 'Bilimsel bir veri sunmuştur.'], 'Yorum eklemeden yalnız davranışları göstermek dolaylı bir yargı iletme yoludur.'),
  ('\'Güçlü olan, her zaman hakkı olan değildir; hakkı olan, her zaman güçlü olandır diyenler ise sadece güçten yanadır.\' Bu cümleyle yazarın savunduğu düşünce hangisidir?', 'Güç ile haklılık aynı şey değildir.', ['Güçlüler daima haklıdır.', 'Hak diye bir şey yoktur.', 'Güçlü olmak gereksizdir.'], 'Cümle, gücü haklılıkla özdeşleştirmeyi reddeder.'),
  ('\'Bir dili öğrenmek, yalnız sözcük öğrenmek değil, o dilin konuşulduğu dünyaya bir kapı açmaktır.\' Bu cümlenin ana düşüncesi hangisidir?', 'Dil öğrenmek, kültürü tanımayı da içerir.', ['Sözcükler gereksizdir.', 'Kapılar önemli değildir.', 'Dil öğrenmek kolaydır.'], 'Dil bir kültüre açılan pencere olarak değerlendirilmiştir.'),
  ('\'Doğa, insandan önce de vardı, insandan sonra da var olacak; sorun, insanın bunu unutup doğayı kendi mülkü sanmasıdır.\' Bu parçanın temel eleştirisi nedir?', 'İnsanın doğayı sahiplenici bir bakışla görmesi', ['Doğanın çok güçlü olması', 'İnsanın doğada yaşaması', 'Doğanın hep aynı kalması'], 'Parça, insanın doğa karşısındaki sahiplenici tutumunu eleştirir.'),
  ('Aynı olayı anlatan iki anlatıcıdan biri ayrıntıları süsleyip kendini kahraman gösteriyor, diğeri sade ve çelişkisiz anlatıyor. Okurun hangi anlatıcıya daha çok güvenmesi beklenir?', 'Sade ve çelişkisiz anlatana', ['Süslü ve kendini öne çıkarana', 'İkisine de eşit düzeyde, çünkü ikisi de aynı olayı anlatıyor', 'Hiçbir anlatıcıya, çünkü iki anlatıcı da aynı ölçüde güvenilmezdir'], 'Tutarlılık ve tarafsızlık, güvenilirliği artıran işaretlerdir.'),
  ('Bir öyküde anlatıcı bir cinayeti anlatırken katilin kim olduğunu sürekli gizliyor; son bölümde anlatıcının kendisinin katil olduğu anlaşılıyor. Bu kurgu hangi anlatıcı türüne örnektir?', 'Güvenilmez anlatıcı', ['Her şeyi bilen anlatıcı', 'Tanık anlatıcı', 'Çoğul anlatıcı'], 'Okuru yanıltan ve gerçeği sonunda açıklayan anlatıcı güvenilmezdir.'),
  ('Bir metinde anlatıcı birinci kişi olarak anlatırken bir süre sonra \'Bana şunu söylediler\' diyerek başka bir kişinin anlatısını aktarıyorsa anlatıda hangi yapı görülür?', 'İç içe anlatı ve aktarılan anlatıcı', ['Düz kronolojik anlatı', 'Gözlemci anlatı', 'Alegorik anlatı'], 'Aktarılan başka bir anlatı, anlatı içinde anlatı yapısını oluşturur.'),
  ('Bir yazar, hikâyesini dinleyicilerin meclis kurup sırayla anlattığı bir toplantı biçiminde kuruyor. Bu yapının geleneksel adı nedir?', 'Çerçeve anlatı', ['Tek parça anlatı', 'Bilinç akışı', 'Mektup roman'], 'Bir toplantı çerçevesinde birden çok anlatıcı olan düzen çerçeve anlatıdır.'),
  ('Bir reklam metni \'Hemen şimdi al, kaçırma!\' diyerek okuru bir eyleme yönlendiriyorsa metnin baskın dil işlevi hangisidir?', 'Çağrı işlevi', ['Göndergesel işlev', 'Heyecan işlevi', 'Şiirsel işlev'], 'Alıcıyı bir eyleme çağıran dil çağrı işlevindedir.'),
  ('Bir romanın ilk sayfasında kahramanın yaşlı bir adam olduğu, ikinci bölümde gençlik yıllarının, üçüncü bölümde ise yeniden yaşlılığının anlatıldığı bir yapı için hangisi söylenebilir?', 'Zaman, geriye dönüşle bölünmüş ve çerçevelenmiştir.', ['Zaman tamamen doğrusaldır.', 'Zaman ileri sıçramalarla kurulmuştur.', 'Zaman hiç kullanılmamıştır.'], 'Baştaki ve sondaki yaşlılık bölümleri, aradaki gençlik anlatısını çerçeveler.'),
  ('Kronolojik bir romanın ortasına bir gün içinde geçen uzun bir sahne yerleştiriliyor. Bu bölümde anlatı hızının yavaşlaması en çok hangi sonucu doğurur?', 'O sahnenin önem ve ağırlık kazanması', ['Olayın önemsizleşmesi', 'Anlatıcının değişmesi', 'Mekânın belirsizleşmesi'], 'Ayrıntılı ve uzun anlatılan sahne yavaşlayarak vurgulanır.'),
  ('Bir kahramanın on yıllık hapis yaşamı tek cümleyle \'Kapı on yıl sonra açıldı.\' biçiminde aktarılıyor. Bu işlem anlatı hızını nasıl etkiler?', 'Hızı artırır; uzun bir süre sıkıştırılmıştır', ['Hızı yavaşlatır', 'Hızı değiştirmez', 'Anlatıyı durdurur'], 'Uzun bir zamanın kısa anlatımı hızı artırır.'),
  ('Bir hikâyenin sonunda anlatıcının \'Ama o gece olanlar, birkaç yıl sonra bambaşka bir anlam kazanacaktı\' demesi okura hangi etkiyi yaratır?', 'Merak ve beklenti uyandırır', ['Olayların bittiğini kesinleştirir', 'Anlatıcıyı güvenilmez kılar', 'Mekânı değiştirir'], 'İleri sıçrama, okurda sonraki olaylara dair beklenti yaratır.'),
  ('Bir trajedide kahraman, tanrıların belirlediği kaderden kaçamıyor. Bu çatışma türü hangisidir?', 'Birey–kader çatışması', ['Birey–doğa çatışması', 'Birey–birey çatışması', 'Birey–toplum çatışması'], 'Kaderin üstünlüğüne karşı verilen mücadele birey–kader çatışmasıdır.'),
  ('Bir roman, kahramanın yoksullukla mücadelesini işlerken toplumdaki sınıf farklarını da gösteriyorsa bu romanda çatışma en çok hangi düzeyde işlenir?', 'Toplumsal düzeyde', ['Yalnız bireysel düzeyde', 'Yalnız doğal düzeyde', 'Çatışma yoktur'], 'Bireyin mücadelesinin toplumsal eşitsizlikle bağlantısı toplumsal çatışmayı gösterir.'),
  ('Bir olay örgüsünde çözüm bölümünde kahramanın amacına ulaşamayıp yenilmesi, eserin hangi türde olabileceğini düşündürür?', 'Trajedi', ['Komedi, güldürüyle toplumu eleştiren oyun', 'Masal', 'Fabl'], 'Kahramanın yıkımıyla biten çözüm trajik bir yapıyı düşündürür.'),
  ('Bir hikâyede \'sürpriz son\' kullanılması ile klasik \'öngörülebilir son\' arasındaki en önemli fark nedir?', 'Sürpriz sonda okurun beklentisi yıkılır', ['Öngörülebilir sonda okur beklentiyi yıkar', 'İkisi de aynı etkiyi yaratır', 'Sürpriz son hep mutludur'], 'Sürpriz son, okurun beklentisini tersine çevirir.'),
  ('Bir romanın olay örgüsü \'ana olay\' çevresinde dönerken çok sayıda yan olayla zenginleştirilmişse bu durum romanın hangi özelliğini gösterir?', 'Çok katmanlı ve kapsamlı bir yapı kurduğunu', ['Tek çizgili ve dar kapsamlı bir yapı kurduğunu', 'Hikâye türüne ait olduğunu', 'Şiir olduğunu'], 'Yan olaylar romanın dokusunu genişletir.'),
  ('Bir oyun sahnede tek bir mekânda ve tek bir günde geçiyor, olaylar ise birbirine sıkı nedensel bağlarla bağlanıyor. Bu yapı hangi kuralla ilişkilidir?', 'Klasik üç birlik kuralıyla', ['Epik tiyatro ilkesiyle, yabancılaştırmaya dayanan yöntemle', 'Absürt tiyatro ilkesiyle', 'Çerçeve öykü yöntemiyle'], 'Tek mekân, tek gün ve tek eylem klasik üç birlik kuralıdır.'),
  ('Aşağıdakilerden hangisi tiyatro ile roman arasındaki temel farklardan biridir?', 'Tiyatro sahnede canlandırılırken roman okunarak algılanır.', ['Tiyatro yalnız nesirle, roman yalnız şiirle yazılır.', 'Tiyatroda olay yoktur.', 'Romanın kişisi yoktur.'], 'Tiyatro canlandırmaya, roman okumaya dayanır.'),
  ('Bir komedide güldürünün \'tekrarlama\' yoluyla yaratılmasına örnek hangisidir?', 'Bir kişinin her sahnede aynı cümleyle ve aynı hatayla ortaya çıkması', ['Kişinin bir kez düşmesi', 'Sahne düzeninin değişmesi', 'Işığın kararması'], 'Aynı tipik davranışın yinelenmesi komik etki doğurur.'),
  ('Bir polisiye romanda okurun da olayın çözümüne katılabilmesi için yazarın hangi yolu izlemesi beklenir?', 'İpuçlarını okurdan saklamadan dağıtması', ['Hiçbir ipucu vermemesi', 'Katili ilk sayfada açıklaması', 'Olayları rastgele sıralaması'], 'Okuru sürece katmak için ipuçları adil biçimde verilir.'),
  ('Bir bilimkurgu romanını başka romanlardan ayıran en belirgin özellik hangisidir?', 'Bilim ve teknolojinin insana etkisinin kurmaca bir dünyada işlenmesi', ['Gerçek olaylara dayanması', 'Yalnız tarihî kişileri anlatması', 'Mektuplardan oluşması'], 'Bilimkurgu, bilimsel hayallerle kurulan dünyada geçer.'),
  ('Ütopya ile distopya arasındaki temel fark hangisidir?', 'Ütopya ideal, distopya kötü ve baskıcı bir toplum tasarlar.', ['İkisi de aynı tür toplum tasarlar.', 'Ütopya geçmişi, distopya şimdiyi anlatır.', 'Distopya yalnız şiirle yazılır.'], 'Ütopya mükemmel, distopya korkutucu ve baskıcı gelecek düzenidir.'),
  ('Aşağıdakilerden hangisi psikolojik romanı diğerlerinden ayıran temel özelliktir?', 'Kişilerin iç dünyasının, duygu ve düşüncelerinin ayrıntılı çözümlenmesi', ['Olayların hızla ilerlemesi', 'Savaş sahnelerinin çokluğu', 'Belge ve rapor kullanımı'], 'Psikolojik romanda ruh çözümlemesi ön plandadır.'),
  ('Bir yazar gençlik yıllarında yaşadığı olayları, adları değiştirerek ama kendi bakışıyla anlatan bir roman yazıyor. Romanı en iyi hangi terim açıklar?', 'Otobiyografik roman', ['Tarihî roman, geçmiş olaylara dayalı kurmaca', 'Bilimkurgu roman', 'Mektup roman'], 'Yazarın kendi yaşamına dayalı kurmaca otobiyografik romandır.'),
  ('Macera romanında okurun ilgisini canlı tutan başlıca öğe hangisidir?', 'Hızlı olay akışı ve beklenmedik karşılaşmalar', ['Ayrıntılı iç çözümleme', 'Kuramsal tartışmalar', 'Uzun dipnotlar'], 'Macera romanı olay temposuna ve serüvene dayanır.'),
  ('Bir romanda kahramanın yaşamı doğumdan ölümüne kadar bütün aşamalarıyla anlatılıyorsa bu romanın kapsamı için hangisi söylenebilir?', 'Geniş zaman kapsamlı, yaşam öyküsü niteliğinde', ['Tek anlık, yoğunlaştırılmış', 'Yalnız mekân odaklı', 'Yalnız diyaloglardan oluşan'], 'Doğumdan ölüme anlatım, geniş zaman kapsamıdır.'),
  ('\'Ev\' ile \'yuva\' sözcükleri aynı yapıyı gösterse de ikincisi daha sıcak bir duygu uyandırır. Bu fark dil bilgisinde en çok hangi kavramla açıklanır?', 'Konotasyon farkı', ['Denotasyon farkı, sözlük anlamının ayrılığı', 'Terim anlam farkı', 'Ses benzerliği'], 'Aynı kavramı gösteren sözcüklerin duygusal çağrışım farkı konotasyondur.'),
  ('Bir şair, \'kara\' sözcüğünü hem rengi hem kederi çağrıştıracak biçimde kullanıyorsa bu durum sözcüğün hangi özelliğini işe koşar?', 'Konotatif (çağrışımsal) anlam katmanını', ['Yalnızca terim anlamını, yani bilim dalındaki kesin karşılığını', 'Yalnızca düz anlamını, yani sözlükteki nesnel karşılığını', 'Dilbilgisel işlevini, yani sözcüğün cümledeki görevini'], 'Renk anlamıyla birlikte keder çağrışımı konotasyonun kullanımıdır.'),
  ('Bilimsel metinlerde sözcüklerin çoğunlukla tek ve kesin anlamla kullanılması, edebî metinlerden hangi farkı gösterir?', 'Düz anlama ve terim anlama dayanmayı, çağrışıma yer vermemeyi', ['Çok anlamlılığı, mecazı ve çağrışımı bilinçli biçimde öne çıkarmayı', 'Mecaz ve imgeyi tercih etmeyi', 'Ahengi ön plana çıkarmayı'], 'Bilimsel dil kesinliği, edebî dil çok anlamlılığı tercih eder.'),
  ('Aşağıdaki dizelerin hangisinde hem teşbih hem mübalağa birlikte bulunur?', 'Gözyaşlarım ırmak gibi taşıp sokakları bastı.', ['Çiçek gibi açıldı yüzü, sabahın ilk ışığında bütün odaya yayıldı.', 'Bu çocuğa kimse bugüne dek kızmadı, kimse sert davranmadı bile.', 'Köyün yolu bu kış da, her kış olduğu gibi, kar altında kalmıştı.'], 'İlk seçenekte hem benzetme edatı (\'gibi\') hem de abartılı bir anlatım vardır.'),
  ('\'Yürek, bir kuş gibi çırpındı göğsümde.\' dizesi ile \'Yürek kuşu çırpındı göğsümde.\' dizesi arasındaki fark nedir?', 'Birincide benzetme edatı vardır; ikincisinde yoktur ve daha güçlü bir benzetmedir.', ['İkisi de aynı güçtedir, çünkü ikisinde de benzetme edatı yoktur.', 'İkincisinde edat vardır, birincisinde yoktur ve ikincisi daha zayıf bir benzetmedir.', 'Birincisi yalnızca istiaredir, ikincisi ise hiçbir benzetme içermez.'], '\'Gibi\' ile yapılan benzetme teşbih, edatsız söylenen güçlü benzetme teşbih-i beliğdir.'),
  ('\'Gece, yıldızlarla işlenmiş siyah bir kadife.\' dizesi hangi söz sanatına örnektir?', 'Teşbih-i beliğ', ['Teşbih, edat ve yönle yapılan benzetme', 'Açık istiare, yalnız kendisine benzetilen söylenen yapı', 'Kinaye, dolaylı anlatım'], 'Benzeyen (gece) ve kendisine benzetilen (kadife) söylenmiş, yön ve edat anılmamıştır.'),
  ('\'Müzik, insanın duygularına en kısa yoldan ulaşır. Sözcükler ise önce zihinden geçer. Bu yüzden bir ezgi, bir cümlenin anlatamadığını kimi zaman bir anda anlatır.\' Bu parçada yazarın temel yargısı hangisidir?', 'Müzik duygulara sözcüklerden daha doğrudan ulaşabilir.', ['Sözcükler müzikten daha etkilidir, çünkü doğrudan zihne ulaşır.', 'Müzik yalnızca bir eğlence aracıdır ve duyguyla ilgisi yoktur.', 'Sözcükler duygulara hiçbir koşulda ulaşamaz, müzik de ulaşamaz.'], 'Parça müziğin duyguya doğrudan ulaşma gücünü vurgular.'),
  ('\'Fotoğraf, bir anı dondurur; yazı ise anıyı akıtır. Biri durmuş zamanı gösterir, öbürü akan zamanı.\' Bu parçada hangi anlatım tekniği öne çıkar?', 'Karşılaştırma', ['Tanık gösterme, bir uzmandan alıntı', 'Sayısal veri kullanma', 'Öyküleme, olay anlatma'], 'Fotoğraf ile yazı yan yana getirilip karşıt yönleri gösterilmiştir.'),
  ('\'Köyün yaşlıları, ağaçların konuştuğunu söylerdi. Rüzgâr yapraklara değdiğinde bir söz fısıldanırdı, ama duymak için susmayı bilmek gerekirdi.\' Bu parçada baskın söz sanatı hangisidir?', 'Teşhis ve intak', ['Mübalağa, abartma', 'Tezat, karşıtlık', 'Cinas, sesteş sözcük'], 'Ağaçların konuşturulması hem teşhis hem intaktır.'),
  ('\'İlk kez denizi gördüğünde on yaşındaydı; şimdi altmış. Onca yıl sonra bile, sahile her inişinde göğsünde aynı dalga kabarırdı.\' Bu parçada zaman anlatımı için ne söylenebilir?', 'Geçmiş ile bugün arasında geçiş yapılarak sürekliliği vurgulanmıştır.', ['Zaman tamamen belirsizdir ve hiçbir yaş bilgisi verilmemiştir.', 'Anlatı yalnızca gelecekte geçer ve yalnız ileri sıçrama vardır.', 'Zamanın anlatıma hiçbir etkisi yoktur, olaylar zamansızdır.'], 'Çocukluk ile altmış yaş arasındaki geçiş, duygunun sürekliliğini gösterir.'),
  ('\'Kitap, kimine göre bir kaçış; kimine göre ise bir dönüş yoludur.\' Bu cümle hangi yargıya yol açar?', 'Kitabın okura farklı anlamlar yüklediğine', ['Kitabın kesin ve tek bir tanımının yapıldığına', 'Bütün kitapların aynı şeyi anlattığına ve aynı etkiyi yarattığına', 'Kitapların gereksiz olduğuna ve okunmaması gerektiğine'], 'Kimine göre kaçış, kimine göre dönüş denmesi, çok anlamlılığı gösterir.'),
  ('Bir paragraf \'Bu nedenle okul kütüphaneleri güçlendirilmelidir.\' cümlesiyle bitiyor. Bu cümlenin paragraftaki işlevi nedir?', 'Önceki düşüncelerden bir sonuç ya da öneri çıkarmak', ['Paragrafa tamamen yeni bir konu açmak', 'Paragraftaki iddiaya somut bir örnek vermek', 'Paragraftaki kavram için kısa bir tanım yapmak'], '\'Bu nedenle\' ile başlayan cümle genellikle sonucu ya da öneriyi bildirir.'),
  ('\'İhtiyar, bastonunu duvara dayadı ve uzun uzun pencereye baktı; sanki orada onu bekleyen biri varmış gibi.\' Bu cümlede kullanılan anlatım türü için ne söylenebilir?', 'Hem öyküleme hem de betimleme vardır.', ['Yalnızca tartışma vardır, çünkü bir görüş savunulmaktadır.', 'Yalnızca açıklama vardır, çünkü bilgi verilmektedir.', 'Yalnızca tanımlama vardır, çünkü bir kavram belirlenmektedir.'], 'Hareketler (öyküleme) ile bakış ve beklenti (betimleme) bir arada verilmiştir.'),
];
